INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A1', 1, 'Будинок моєї сім''ї', '["Наша сім''я живе в будинку біля парку. У будинку живуть мама, тато, мій брат і я. Мама працює в школі, тато в магазині, а брат ходить у дитячий садок. Уранці всі поспішають, але ввечері ми знову разом.","На першому поверсі є кухня і вітальня. На кухні мама часто готує суп, а у вітальні ми дивимося телевізор. Там стоїть диван, стіл і велика шафа. У шафі лежать книжки і настільні ігри. На другому поверсі є наші спальні.","Моя кімната невелика, але в ній є ліжко, стіл і книжки. У дворі тато ставить лавку, і влітку ми сидимо там разом. Брат грається з м''ячем, а я дивлюся на дерева. Наш дім простий, але рідний."]', 1, 1, 1) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 1), 1, 'Де живе сім''я?', 'У будинку біля парку', '["У машині","У школі","На пошті"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 1), 2, 'Хто живе в будинку?', 'Мама, тато, брат і я', '["Тільки мама","Три друзі","Учитель і клас"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 1), 3, 'Де мама готує суп?', 'На кухні', '["У дворі","У ванній","У бібліотеці"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 1), 4, 'Що є в кімнаті автора?', 'Ліжко, стіл і книжки', '["Гойдалка","Авто","Пошта"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 1), 5, 'Що тато ставить у дворі?', 'Лавку', '["Шафу","Двері","Машину"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A1', 2, 'Книги та іграшки', '["Мене звати Софійка, і я дуже люблю книги та іграшки. У моїй кімнаті є полиця з казками і велика коробка з іграшками. Я часто сиджу біля полиці після школи. Спочатку я вибираю книжку, а потім відкриваю коробку.","Щовечора я читаю коротку книжку з малюнками. Моя улюблена книжка розповідає про дівчинку і ліс. Я читаю її багато разів, бо добре знаю героїв. Іноді мама слухає мене і допомагає читати нові слова.","У коробці лежать кубики, лялька і маленька машина. З кубиків я будую будинок, а лялька живе в цьому будинку. Коли мама читає зі мною, я повторюю нові слова. Потім я граюся і вигадую маленьку історію. Іноді я записую ім''я героя на папері і малюю поруч маленький будинок."]', 1, 1, 2) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 2), 1, 'Що любить Софійка?', 'Книги та іграшки', '["Машини","Пошту","Спорт"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 2), 2, 'Де стоять казки?', 'На полиці', '["У машині","У дворі","На столі вчителя"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 2), 3, 'Про що улюблена книжка?', 'Про дівчинку і ліс', '["Про пошту","Про машину","Про собаку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 2), 4, 'Що Софійка будує з кубиків?', 'Будинок', '["Місто","Машину","Школу"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 2), 5, 'Де лежить маленька машина?', 'У коробці', '["На ліжку","У саду","У сумці"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A1', 3, 'Мій будинок', '["Я живу в невеликому будинку біля саду. У будинку є чотири кімнати: кухня, спальня, вітальня і ванна кімната. Біля дверей стоїть полиця для ключів і взуття. На кухні стоїть стіл і чотири стільці. Уранці ми снідаємо там разом і говоримо про день.","У вітальні стоїть диван, низький столик і годинник на стіні. На дивані лежить теплий плед. У моїй спальні є ліжко, шафа і лампа біля ліжка. На столі лежать книжка і телефон. Я люблю свій будинок, бо він теплий і спокійний. Увечері я читаю у вітальні, а мама п''є чай на кухні. На вихідних я прибираю кімнату і ставлю книжки на свою полицю."]', 1, 1, 3) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 3), 1, 'Скільки кімнат має будинок?', 'Чотири', '["Дві","Шість","Одна"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 3), 2, 'Що стоїть на кухні?', 'Стіл і стільці', '["Ліжко","Диван","Велосипед"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 3), 3, 'Де стоїть диван?', 'У вітальні', '["У ванній","У саду","На пошті"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 3), 4, 'Що є біля ліжка?', 'Лампа', '["Машина","Гойдалка","Миска"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 3), 5, 'Який будинок?', 'Теплий і спокійний', '["Шумний і холодний","Старий і темний","Великий і порожній"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A1', 4, 'Мій день', '["Уранці я прокидаюся і відкриваю вікно. У кімнаті стає свіжо і світло. Потім я вмиваюся і зачісуюся перед дзеркалом. На кухні я їм хліб із сиром і п''ю воду.","Після сніданку я йду до школи. У школі я читаю, пишу і слухаю вчителя. Після уроків я обідаю і роблю вправи. Потім я складаю книжки на стіл.","Увечері я гуляю біля дому. Потім я дивлюся мультфільм, а мама готує вечерю. Я вечеряю з родиною і мию свою тарілку. Потім я рано лягаю спати."]', 1, 1, 4) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 4), 1, 'Що герой робить уранці?', 'Відкриває вікно', '["Купує машину","Йде на пошту","Грає в м''яч"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 4), 2, 'Що герой їсть на сніданок?', 'Хліб і сир', '["Суп","Морозиво","Рибу"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 4), 3, 'Куди герой йде після сніданку?', 'До школи', '["До моря","До бабусі","В автосалон"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 4), 4, 'Що герой робить після уроків?', 'Обідає і робить вправи', '["Купує квіти","Пише адресу","Їде в парк"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 4), 5, 'Що герой дивиться ввечері?', 'Мультфільм', '["Розклад","Карту","Квитанцію"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A1', 5, 'Мій звичайний день', '["Я прокидаюся о сьомій годині і не поспішаю вставати. Потім я йду у ванну кімнату, мию обличчя і чищу зуби. На кухні я їм кашу і п''ю теплий чай. Після сніданку я перевіряю сумку і беру ключі.","До школи я йду пішки. На уроках я слухаю вчителя, читаю текст і пишу в зошиті. На перерві я їм яблуко і говорю з другом. Ми часто говоримо про футбол або домашнє завдання. Після школи я повертаюся додому.","Удома я обідаю і трохи відпочиваю. Потім я роблю домашнє завдання, гуляю з другом і вечеряю з родиною. Перед сном я кладу книжки в сумку і ставлю будильник. Якщо я все готую ввечері, ранок проходить легко."]', 1, 1, 5) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 5), 1, 'Коли герой прокидається?', 'О сьомій годині', '["О десятій годині","Опівночі","О першій годині"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 5), 2, 'Що герой їсть на перерві?', 'Яблуко', '["Млинці","Суп","Морозиво"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 5), 3, 'Куди герой йде після уроків?', 'Додому', '["На пошту","До моря","В автосалон"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 5), 4, 'Що герой робить увечері?', 'Гуляє з другом', '["Купує машину","Малює квіти","Пише лист"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 5), 5, 'Що герой ставить перед сном?', 'Будильник', '["Чайник","Тарілку","Стілець"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A1', 6, 'Мої домашні тварини', '["У мене вдома живуть кіт і два собаки. Кота звати Мурчик. Він сірий, тихий і любить сидіти біля вікна. Уранці Мурчик дивиться на двір і чекає сніданок. Першого собаку звати Бім, а другого Рекс. Бім великий і добрий, а Рекс малий і швидкий.","Щодня я годую тварин. Коту я даю їжу в миску, а собакам даю воду і сухий корм. Після їжі Рекс біжить у двір, а Бім лягає біля дверей. Увечері всі лежать біля мене, і вдома стає спокійно. Мама теж часто гладить Мурчика."]', 1, 1, 6) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 6), 1, 'Які тварини є вдома?', 'Кіт і два собаки', '["Два коти","Кіт і птах","Три собаки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 6), 2, 'Як звати кота?', 'Мурчик', '["Бім","Рекс","Тедді"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 6), 3, 'Де любить сидіти Мурчик?', 'Біля вікна', '["У школі","На пошті","У машині"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 6), 4, 'Який Рекс?', 'Малий і швидкий', '["Сірий і тихий","Великий і добрий","Старий і сумний"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 6), 5, 'Що автор дає собакам?', 'Воду і сухий корм', '["Чай і хліб","Книжки","Квіти"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A1', 7, 'Мої канікули', '["У мене починаються канікули, і я не йду до школи. Уранці я сплю довше, а потім повільно снідаю. Мама готує млинці, а я п''ю чай і дивлюся у вікно.","Удень я гуляю з друзями в парку. Там є гойдалка, лавка і велика доріжка. Ми граємо в м''яч, а потім купуємо морозиво.","Увечері я читаю книжку або допомагаю вдома. Я мию тарілки після обіду і складаю іграшки в коробку. У серпні ми їдемо до Одеси, тому я дуже чекаю цю поїздку. Я хочу бачити море і збирати мушлі на пляжі. На канікулах день довгий, і я маю більше часу для гри, читання та прогулянок."]', 1, 1, 7) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 7), 1, 'Що починається у героя?', 'Канікули', '["Уроки","Робота","Тест"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 7), 2, 'Що готує мама?', 'Млинці', '["Суп","Пасту","Рибу"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 7), 3, 'Куди герой іде з друзями?', 'У парк', '["На пошту","У бібліотеку","У гараж"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 7), 4, 'Що друзі купують?', 'Морозиво', '["Марку","Машину","Шафу"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 7), 5, 'Куди сім''я їде в серпні?', 'До Одеси', '["До Києва","До школи","До магазину"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A1', 8, 'Моя м''яка іграшка', '["У мене є улюблена м''яка іграшка. Це коричневий ведмедик, якого звати Тедді. У нього круглі вуха, чорні очі і дуже м''які лапи. Він невеликий, тому я легко беру його з собою.","Тедді сидить на моєму ліжку майже весь день. Увечері я беру його в руки, читаю книжку і відпочиваю. Коли мені сумно, ведмедик завжди лежить поруч.","Мама подарувала мені Тедді на день народження. Іграшка вже не нова, але вона дуже дорога для мене. Я часто ставлю Тедді на подушку і кажу йому добраніч."]', 1, 1, 8) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 8), 1, 'Яка м''яка іграшка є в героя?', 'Ведмедик', '["Лялька","Машина","Кубик"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 8), 2, 'Як звати ведмедика?', 'Тедді', '["Мурчик","Бім","Данило"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 8), 3, 'Де сидить ведмедик?', 'На ліжку', '["У дворі","У машині","На пошті"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 8), 4, 'Хто подарував ведмедика?', 'Мама', '["Тато","Учитель","Сусід"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 8), 5, 'Який ведмедик?', 'Коричневий і м''який', '["Білий і швидкий","Новий і холодний","Червоний і твердий"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A1', 9, 'Моя чудова родина', '["У мене є чудова родина. Моя мама добра і спокійна, вона готує сніданок і часто читає книжки. Мій тато веселий, він працює в офісі і любить музику.","У мене є сестра Ліза. Вона ходить до школи і любить малювати квіти. Ще у нас є дідусь, який часто розповідає цікаві історії. У неділю він приходить до нас на обід.","Увечері ми сидимо разом на кухні. Ми п''ємо чай, говоримо про день і сміємося. Ліза показує малюнок, тато слухає, а мама усміхається. Я дуже люблю свою родину. Коли мені потрібна допомога, родина завжди поруч. Тому вдома мені легко і тепло."]', 1, 1, 9) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 9), 1, 'Яка родина у героя?', 'Чудова', '["Мала і сумна","Нова","Далека"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 9), 2, 'Що робить мама?', 'Готує сніданок і читає книжки', '["Водить машину","Продає марки","Грає в шахи"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 9), 3, 'Як звати сестру?', 'Ліза', '["Оля","Софійка","Марта"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 9), 4, 'Що любить Ліза?', 'Малювати квіти', '["Купувати машини","Писати адресу","Годувати кота"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 9), 5, 'Що сім''я робить увечері?', 'П''є чай і говорить', '["Йде до школи","Купує корм","Їде до моря"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A1', 10, 'На пошті', '["Сьогодні я йду на пошту, бо маю лист для тітки. Пошта стоїть біля магазину. Я кладу лист у сумку і беру адресу.","На пошті працює привітна жінка. У залі тихо, і переді мною стоїть тільки один чоловік. Вона питає адресу, і я читаю її з паперу. Потім жінка бере лист, дає марку, і я плачу гроші.","Після цього я беру квитанцію і кажу: Дякую. Біля пошти стоїть лавка, тому я сідаю на хвилину. Увечері я кажу мамі, що лист уже їде до тітки."]', 1, 1, 10) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 10), 1, 'Куди йде герой?', 'На пошту', '["До школи","У парк","В автосалон"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 10), 2, 'Для кого є лист?', 'Для тітки', '["Для тата","Для вчителя","Для собаки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 10), 3, 'Що питає жінка?', 'Адресу', '["Розклад","Колір","Ім''я кота"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 10), 4, 'Що жінка дає?', 'Марку', '["Квіти","Машину","Іграшку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 10), 5, 'Що герой бере в кінці?', 'Квитанцію', '["Ключ","Миску","Книжку"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A1', 11, 'Нова машина для сім''ї', '["Моя сім''я хоче купити нову машину, бо стара машина часто стоїть у гаражі. Тато дивиться машини в телефоні, а мама думає про колір і місце для сумок. Я хочу зручне заднє сидіння. Нам потрібна машина для роботи, школи і поїздок до бабусі.","У суботу ми йдемо в автосалон. Там стоїть біла машина, вона чиста, велика і дуже гарна. Тато сідає за кермо, мама відкриває багажник, а я сідаю назад. Продавець показує нам двері, фари і нові колеса.","Ми купуємо цю машину і їдемо додому повільно. Тато веде машину обережно, мама усміхається, а я дивлюся у вікно. Тепер ми можемо зручно їздити до бабусі."]', 1, 1, 11) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 11), 1, 'Що хоче купити сім''я?', 'Нову машину', '["Новий будинок","Новий стіл","Нову шафу"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 11), 2, 'Де сім''я дивиться машину?', 'В автосалоні', '["У бібліотеці","На пошті","У школі"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 11), 3, 'Якого кольору машина?', 'Біла', '["Чорна","Синя","Червона"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 11), 4, 'Хто сідає за кермо?', 'Тато', '["Мама","Сусід","Дитина"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 11), 5, 'Що показує продавець?', 'Двері, фари і колеса', '["Ключі і карту","Книжку і зошит","Стіл і шафу"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A1', 12, 'Новий однокласник', '["Сьогодні в наш клас приходить новий хлопець. Його звати Данило, і він сідає біля мене. Я кажу: Привіт, мене звати Оля. Данило усміхається і відповідає: Привіт, дуже приємно. Учитель просить нас показати Данилу розклад.","На перерві я питаю Данила, де він живе. Він каже, що живе біля парку. Потім ми говоримо про хобі. Данило любить футбол і шахи, а я люблю футбол і книжки.","Після уроків ми разом ідемо додому. Завтра ми знову сидимо поруч у класі. Він показує мені новий пенал, а я показую йому шкільний двір. Мені легко говорити з ним українською."]', 1, 1, 12) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 12), 1, 'Як звати нового хлопця?', 'Данило', '["Максим","Богдан","Рекс"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 12), 2, 'Хто знайомиться з Данилом?', 'Оля', '["Ліза","Софійка","Мама"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 12), 3, 'Де живе Данило?', 'Біля парку', '["Біля моря","На пошті","У гаражі"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 12), 4, 'Що любить Данило?', 'Футбол і шахи', '["Молоко і чай","Квіти і суп","Пошту і марки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 12), 5, 'Куди діти йдуть після уроків?', 'Додому разом', '["В автосалон","До бабусі","На море"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A1', 13, 'Поїздка з мамою', '["Сьогодні я їду з мамою на машині до бабусі. Мама сидить за кермом, а я сиджу поруч і тримаю квіти. У машині грає тиха музика, тому дорога здається приємною. Мама питає мене про школу, і я розповідаю про уроки.","Ми їдемо через місто і бачимо магазин, аптеку та школу. Потім машина їде біля річки, і я дивлюся на воду. Мама питає, чи я взяв подарунок, і я показую квіти. Я також беру маленький пиріг у коробці.","Через двадцять хвилин ми приїжджаємо. Бабуся стоїть біля воріт і радіє нам. Я даю їй квіти, мама ставить сумку на стілець, і ми сідаємо за стіл."]', 1, 1, 13) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 13), 1, 'З ким герой їде на машині?', 'З мамою', '["З татом","З учителем","З другом"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 13), 2, 'Куди вони їдуть?', 'До бабусі', '["До школи","На пошту","У бібліотеку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 13), 3, 'Що герой бере для бабусі?', 'Квіти', '["Книжку","М''яч","Лист"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 13), 4, 'Що грає в машині?', 'Тиха музика', '["Гучний фільм","Урок","Новини"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 13), 5, 'Де стоїть бабуся?', 'Біля воріт', '["Біля школи","У магазині","У парку"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A1', 14, 'Розклад занять студента', '["Мене звати Максим, і я навчаюся в коледжі в Києві. У понеділок я встаю о сьомій годині, бо перше заняття починається о дев''ятій. Я беру зошит, ручку, книжку і йду до школи. Біля входу я зустрічаю друга Андрія. Ми разом ідемо в клас і дивимося розклад на дверях.","Після занять я заходжу в бібліотеку. Там тихо, тому я читаю текст і роблю домашнє завдання. У середу в мене українська мова і математика, а в четвер історія. У п''ятницю ми пишемо короткий тест. Увечері я готую сумку, перевіряю олівці і заряджаю телефон. Потім я трохи відпочиваю вдома."]', 1, 1, 14) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 14), 1, 'Де навчається Максим?', 'У коледжі', '["У лікарні","На пошті","У магазині"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 14), 2, 'Куди Максим йде після занять?', 'У бібліотеку', '["У парк","На пошту","У магазин"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 14), 3, 'Що Максим бере на заняття?', 'Зошит, ручку і книжку', '["М''яч і шапку","Ключі і квіти","Молоко і хліб"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 14), 4, 'Коли Максим має короткий тест?', 'У п''ятницю', '["У неділю","У суботу","У понеділок"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A1' AND display_order = 14), 5, 'Що Максим робить увечері?', 'Готує сумку', '["Пише тест","Іде в клас","Зустрічає друга"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 1, 'Мій день', '["Будильник дзвонить о сьомій, і я розплющую очі. У кухні вже пахне чаєм. Мама гукає з коридору: «Олю, вставай!» Я вмиваюся, застеляю ліжко і йду на кухню. На столі вже стоїть тепла каша з медом. Я снідаю, беру рюкзак і виходжу з дому.","О восьмій годині я вже стою біля школи. Дорога недовга, тому я ніколи не поспішаю. У школі в мене чотири уроки, перерва і обід. Найбільше я люблю сидіти біля вікна, бо звідти видно старий каштан у дворі. На перерві ми з подругою їмо яблука. Після уроків ще трохи розмовляємо біля воріт.","Додому я приходжу о третій. Спочатку відпочиваю, а потім роблю домашнє завдання. Увечері я читаю книжку про далекі мандри. За вікном темніє, і в кімнаті стає тихо. Я закриваю книжку і всміхаюся: день був простий і добрий."]', 1, 1, 1) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 1), 1, 'О котрій годині Оля прокидається?', 'О сьомій ранку', '["О третій годині","О восьмій вечора","Опівночі"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 1), 2, 'Що Оля їсть на сніданок?', 'Кашу', '["Борщ","Вареники","Морозиво"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 1), 3, 'Куди Оля йде о восьмій годині?', 'До школи', '["До магазину","До бабусі","До басейну"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 1), 4, 'Коли Оля приходить додому?', 'О третій годині', '["О сьомій ранку","О восьмій годині","Після вечері"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 1), 5, 'Що Оля читає ввечері?', 'Книжку про мандри', '["Газету","Лист","Розклад уроків"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 2, 'Моя сім''я', '["Удома мене кличуть Тарасиком, а в школі — Тарасом. Нас у сім''ї четверо. Мама, тато, молодша сестра Марійка і я. Ми живемо в маленькому будинку біля саду. Влітку там цвітуть старі яблуні, і вікна нашої кухні дивляться прямо на них.","Мама працює в школі, а тато — в майстерні. Марійка ще ходить у дитячий садок. Вона любить малювати і щовечора показує мені нові картинки. Я кажу, що вони гарні, і вона одразу біжить по нові олівці. Увечері ми вечеряємо разом і розповідаємо, як минув день. Тато завжди питає першим.","У суботу ми прибираємо, готуємо обід і нікуди не поспішаємо. Тато вмикає радіо, а Марійка сідає малювати просто на підлозі. Мама розливає гарячий чай у великі чашки. Я люблю свою сім''ю саме за такі дні. У такі хвилини ніхто не дивиться на годинник."]', 1, 1, 2) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 2), 1, 'Як звати хлопця в історії?', 'Тарас', '["Іван","Дмитро","Колін"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 2), 2, 'Хто є в сім''ї Тараса?', 'Мама, тато і молодша сестра', '["Тільки мама і тато","Бабуся і дідусь","Два брати"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 2), 3, 'Де живе сім''я Тараса?', 'У маленькому будинку біля саду', '["У великому готелі","У школі","Біля моря"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 2), 4, 'Що любить робити Марійка?', 'Малювати', '["Плавати","Готувати борщ","Грати у футбол"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 2), 5, 'Що для Тараса дуже важливе?', 'Час разом із сім''єю', '["Довга дорога","Новий магазин","Холодна погода"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 3, 'Мій будинок', '["Я живу з батьками у квартирі на третьому поверсі. Наш будинок стоїть біля невеликого магазину і автобусної зупинки. Квартира не дуже велика, але світла, тепла і зручна. У ній є кухня, вітальня і дві кімнати. З вікна видно тихий двір, лавку і кілька старих дерев.","На кухні ми снідаємо і говоримо про плани на день. У вітальні стоїть диван, круглий столик і полиця з книжками. Увечері там тихо, тому мама часто читає, а тато відпочиває після роботи. Найбільше в цій квартирі мені подобається моя кімната. Я роблю уроки біля вікна, а потім слухаю музику або читаю.","Торік ми з татом пофарбували тут стіни, і я сам вибрав колір. Тут тепло і тихо. Я сідаю біля вікна і довго не хочу нікуди йти."]', 1, 1, 3) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 3), 1, 'На якому поверсі живе оповідач?', 'На третьому поверсі', '["На першому поверсі","На десятому поверсі","У підвалі"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 3), 2, 'Що є у квартирі?', 'Кухня, вітальня і дві кімнати', '["Три кухні","Сад і гараж","Клас і бібліотека"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 3), 3, 'Де сім''я снідає?', 'На кухні', '["У дворі","У магазині","У школі"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 3), 4, 'Що стоїть у вітальні?', 'Диван, столик і полиця з книжками', '["Ліжко і шафа","Плита і холодильник","Гойдалка і пісок"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 3), 5, 'Яка кімната найбільше подобається оповідачу?', 'Моя кімната', '["Кухня","Вітальня","Під''їзд"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 4, 'У школі', '["Я навчаюся в п''ятому класі. У нас аж дві Марини, тому мене всі кличуть Маринкою. Школа стоїть недалеко від дому, тому вранці можу йти зовсім повільно. У класі в мене є подруги, з якими я сиджу на перервах.","Мій улюблений предмет — математика. Мені подобається рахувати, розв''язувати задачі і знаходити правильну відповідь. Коли задача важка, я не здаюся одразу, а читаю умову ще раз. Учителька спокійно допомагає нам і ніколи не сварить. Сьогодні в нас також є урок малювання. Вона роздає нам аркуші і кольорові олівці.","Ми малюємо осінній парк, жовте листя і лавку біля дерева. Я довго вибираю потрібний олівець. На перерві ми обговорюємо малюнки і сміємося з маленьких помилок. Свою роботу я кладу в папку дуже обережно. Додому я йду з гарним настроєм."]', 1, 1, 4) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 4), 1, 'У якому класі навчається Маринка?', 'У п''ятому класі', '["У першому класі","У дев''ятому класі","У дитячому садку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 4), 2, 'Який улюблений предмет Маринки?', 'Математика', '["Музика","Історія","Географія"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 4), 3, 'Що робить Маринка, коли задача важка?', 'Читає умову ще раз', '["Одразу йде додому","Не відкриває зошит","Малює листівку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 4), 4, 'Який урок є сьогодні?', 'Урок малювання', '["Урок плавання","Урок співу","Урок кулінарії"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 4), 5, 'З яким настроєм Маринка йде додому?', 'З гарним настроєм', '["Зі страхом","Зі злістю","Без настрою"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 5, 'Мій друг', '["Мого найкращого друга звати Іван. Ми живемо на одній вулиці і ходимо до однієї школи. Зранку він чекає мене біля свого двору, навіть коли йде дощ. Потім ми разом ідемо на уроки і говоримо про футбол або домашнє завдання.","Іван веселий і добрий. На перервах ми часто стоїмо біля вікна або розмовляємо з однокласниками. Після школи ми майже щодня граємо у футбол на майданчику. Іван добре бігає і часто забиває голи, але ніколи не хвалиться. Я стою на воротах, бо бігаю гірше.","Коли мені важко, Іван допомагає. Він може пояснити задачу або дати мені потрібний зошит. Торік я довго хворів, і він щодня приносив мені домашнє завдання. Я теж стараюся бути таким другом для нього. У неділю ми телефонуємо одне одному і плануємо гру на понеділок."]', 1, 1, 5) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 5), 1, 'Як звати найкращого друга оповідача?', 'Іван', '["Тарас","Олег","Богдан"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 5), 2, 'Куди хлопці ходять разом?', 'До школи', '["На роботу","До лікаря","На ринок"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 5), 3, 'Про що вони говорять дорогою?', 'Про футбол або домашнє завдання', '["Про погоду і каву","Про море і готель","Про листи і марки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 5), 4, 'У що друзі інколи грають після школи?', 'У футбол', '["У шахи","У теніс","У карти"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 5), 5, 'За що оповідач вдячний Іванові?', 'За допомогу', '["За новий рюкзак","За обід","За квиток"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 6, 'У магазині', '["Мама: Добрий день. Мені, будь ласка, молоко, хліб і кілограм яблук. Продавчиня: Добрий день. Молоко у холодильнику біля входу, а свіжий хліб щойно привезли. Мама: Тоді візьму дві пляшки молока і одну хлібину. Продавчиня: Хліб іще теплий. Беріть, поки не охолов. Мама: Дуже добре. А які яблука сьогодні найсолодші? Продавчиня: Ось ці червоні, з нового врожаю. Вони солодкі й зовсім недорогі. Мама: Тоді покладіть кілограм, будь ласка. Продавчиня: Готово. Щось іще потрібно? Мама: А пакет у вас є? Продавчиня: Так, звичайно. Мама: Ні, дякую, більше нічого. Де у вас каса? Продавчиня: Каса праворуч, біля вікна. Я вас проведу. Мама: Дякую. Я плачу карткою. Продавчиня: Ось ваш чек. Гарного вечора! Мама складає молоко, хліб і яблука в торбу, дякує ще раз і виходить. На вулиці вже пахне дощем."]', 1, 1, 6) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 6), 1, 'Що мама хоче купити в магазині?', 'Молоко, хліб і яблука', '["Каву, сир і рибу","Книжку, ручку і зошит","Картоплю, рис і чай"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 6), 2, 'Де стоїть молоко?', 'У холодильнику', '["Біля вікна","На підлозі","У торбі"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 6), 3, 'Які яблука бере мама?', 'Червоні яблука', '["Зелені груші","Жовті банани","Сині сливи"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 6), 4, 'Як мама платить?', 'Карткою', '["Готівкою","Чеком","Квитком"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 6), 5, 'Що мама робить після покупки?', 'Кладе продукти в торбу і виходить', '["Залишається в магазині","Повертає яблука","Пише лист"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 7, 'Мій улюблений спорт', '["У вівторок і четвер я після школи йду не додому, а в басейн. Мене звати Соня, і плавання — мій улюблений спорт. Два рази на тиждень — і цього мені досить. Беру сумку, купальник і великий рушник. Басейн зовсім недалеко від нашої школи.","У басейні нас зустрічає тренерка. Вона показує, як рухати руками і спокійно дихати у воді. Спочатку я роблю вправи біля бортика, а потім пливу повільно. Я не поспішаю, бо хочу зробити все правильно. Після заняття руки важкі, але я знаю, що стаю сильнішою.","Удома я розповідаю мамі, що сьогодні пливла краще. Мама усміхається і наливає мені гарячий чай. Я вже думаю про наступний вівторок. У сумці сохне купальник, а рушник висить на батареї біля вікна. Наступного тижня я знову піду до басейну після уроків."]', 1, 1, 7) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 7), 1, 'Який улюблений спорт Соні?', 'Плавання', '["Футбол","Біг","Танці"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 7), 2, 'Скільки разів на тиждень Соня плаває?', 'Два рази', '["Один раз","Кожен день","П''ять разів"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 7), 3, 'Куди Соня йде після школи?', 'До басейну', '["До парку","До магазину","До бібліотеки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 7), 4, 'Хто зустрічає дітей у басейні?', 'Тренерка', '["Лікарка","Продавчиня","Бабуся"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 7), 5, 'Чому Соня хоче продовжувати плавати?', 'Бо спорт допомагає їй бути сильною', '["Бо вона хоче купити човен","Бо там дають морозиво","Бо школа далеко"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 8, 'Погода сьогодні', '["Сьогодні ранок хмарний і холодний. Я дивлюся у вікно й бачу сіре небо над будинками. У дворі немає сонця, і мокрі дерева стоять зовсім нерухомо. На вулиці дме вітер, тому я надягаю теплу куртку і шарф. Мама каже з кухні: «Дмитре, шапку не забудь.» Дощу поки немає, але погода все одно неприємна. До школи я йду швидко і весь час тримаю руки в кишенях.","Після уроків я нарешті повертаюся додому. У під''їзді вже тепліше, і мені стає легше. Вдома я знімаю куртку, вішаю шарф біля дверей і п''ю гарячий чай. У кімнаті затишно, а на столі світить маленька настільна лампа. Я чую, як за вікном тихо шумить холодний вітер. Мама приносить плед і вмикає радіо на кухні. Сідаю робити домашнє завдання і зовсім не хочу нікуди виходити."]', 1, 1, 8) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 8), 1, 'Який сьогодні ранок?', 'Хмарний і холодний', '["Сонячний і теплий","Спекотний і сухий","Тихий і літній"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 8), 2, 'Що Дмитро бачить у вікно?', 'Сіре небо', '["Синє море","Святковий стіл","Новий парк"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 8), 3, 'Що Дмитро надягає на вулицю?', 'Теплу куртку і шарф', '["Футболку і шорти","Костюм для плавання","Святкову сорочку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 8), 4, 'Що Дмитро п''є вдома?', 'Гарячий чай', '["Холодний сік","Какао","Молоко"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 8), 5, 'Як Дмитро почувається вдома?', 'Затишно', '["Голодно і сумно","Сердито","Дуже холодно"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 9, 'Що я їм на сніданок', '["Щоранку на кухні пахне кашею з медом. Це мій сніданок, і він не змінюється роками. Мама варить кашу на маленькій плиті, поки я вмиваюся і збираю рюкзак. Вона тепла і трохи солодка. Друзі звуть мене Настею і сміються, що я щоранку їм те саме.","Іноді я п''ю какао, особливо коли надворі холодно. У чашці воно пахне шоколадом, і ранок стає приємнішим. Я не їм багато різних страв, бо вранці часу мало. Але кілька ложок каші з медом я їм завжди. Мама називає це найкращим початком дня.","Після сніданку в мене з''являється енергія на цілий ранок. Я краще слухаю вчительку і не думаю про їжу до перерви. Потім беру куртку, кажу мамі до побачення і виходжу з дому. Тепер я готова до нового дня."]', 1, 1, 9) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 9), 1, 'Що Настя їсть щоранку?', 'Кашу з медом', '["Піцу","Борщ","Вареники"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 9), 2, 'Коли Настя іноді п''є какао?', 'Коли надворі холодно', '["Коли йде до басейну","Коли купує хліб","Коли малює парк"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 9), 3, 'Чому Настя не їсть багато різних страв уранці?', 'Бо часу мало', '["Бо немає тарілок","Бо вона не любить сніданок","Бо школа далеко"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 9), 4, 'Що дає Насті сніданок?', 'Енергію', '["Новий рюкзак","Книжку","Малюнок"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 9), 5, 'Що Настя робить після сніданку?', 'Бере куртку і виходить з дому', '["Лягає спати","Іде до магазину","Готує вечерю"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 10, 'Мої домашні тварини', '["Кота я назвав Рудиком, бо він рудий. Мене звати Колін, і Рудик живе в нас уже три роки. Він м''який і дуже спокійний. Уранці Рудик сидить біля миски і чекає на їжу. Коли я насипаю корм, він тихо муркоче і дивиться на мене зеленими очима.","Удень Рудик часто спить на дивані у вітальні. Він любить тепле місце біля великої подушки. Якщо хтось сідає поруч, кіт відкриває одне око, але не встає. Мама сміється і каже, що Рудик справжній господар дивана.","Щовечора я граюся з Рудиком після уроків. Я кидаю йому маленький м''ячик, а він біжить за ним по кімнаті. Потім він лягає біля моїх ніг, коли я читаю. Я гладжу його по спині і чую, як він муркоче. У такі хвилини я завжди усміхаюся."]', 1, 1, 10) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 10), 1, 'Як звати кота Коліна?', 'Рудик', '["Мурчик","Барсик","Сірко"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 10), 2, 'Який Рудик?', 'Рудий, м''який і спокійний', '["Білий і швидкий","Чорний і сердитий","Сірий і шумний"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 10), 3, 'Де Рудик часто спить удень?', 'На дивані', '["На балконі","У школі","У саду"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 10), 4, 'Коли Колін грається з Рудиком?', 'Щовечора після уроків', '["Щоранку перед сніданком","Тільки в неділю","Під час уроків"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 10), 5, 'Що Коліну подобається робити з котом?', 'Гратися з ним після уроків', '["Купувати хліб","Писати лист","Готувати кашу"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 11, 'Маршрутка або автобус', '["Моя зупинка — біля невеликого магазину на розі. Мене звати Андрій, і щодня я їжджу на роботу цим автобусом. З дому я виходжу раніше, бо не люблю поспішати. Автобуса треба чекати хвилин десять. Я стою біля дороги і дивлюся, як повільно прокидається вулиця.","Коли автобус приїжджає, я заходжу через передні двері. Квиток коштує дев''ять гривень, тому дрібні гроші я готую заздалегідь. У салоні часто багато людей, але їхати мені недовго. Я тримаюся за поручень і дивлюся у вікно. За склом пропливають будинки, мокрі дерева і ранкові вітрини.","Біля роботи я виходжу на третій зупинці від дому. Потім іду пішки повз аптеку і кав''ярню, де вранці завжди пахне кавою. Дорога проста, тому я ніколи не плутаюся. На роботу я приходжу вчасно і встигаю випити чаю."]', 1, 1, 11) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 11), 1, 'Як Андрій їде на роботу щодня?', 'Автобусом', '["Метром","Велосипедом","Потягом"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 11), 2, 'Де знаходиться зупинка Андрія?', 'Біля невеликого магазину', '["Біля школи","Біля лікарні","Біля парку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 11), 3, 'Скільки часу Андрій зазвичай чекає на автобус?', 'Приблизно десять хвилин', '["Одну хвилину","Пів години","Цілу годину"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 11), 4, 'Скільки коштує квиток?', 'Дев''ять гривень', '["П''ять гривень","Двадцять гривень","П''ятнадцять гривень"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 11), 5, 'На якій зупинці Андрій виходить біля роботи?', 'На третій зупинці', '["На першій зупинці","На п''ятій зупинці","На останній зупинці"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 12, 'У лікаря', '["Аня: Добрий день, лікарю. Я погано почуваюся. У мене болить горло, і я швидко втомлююся на уроках. Лікар: Добрий день, Аню. Сідай, будь ласка. Скажи, коли це почалося? Аня: Позавчора ввечері, після довгої прогулянки. Лікар: Це схоже на звичайну застуду, але тобі треба добре відпочити. Аня: А я можу завтра піти до школи? У нас важливий урок. Лікар: Краще залишись удома. Пий теплий чай, більше спи і не виходь на холод. Нехай мама допоможе тобі з уроками. Аня: А ліки потрібні? Лікар: Поки ні, головне — тепло і сон. Аня: Добре, я послухаю вас. Лікар: Через три дні тобі має стати значно краще. Удома Аня п''є теплий чай, лежить у ліжку і читає просту книжку. Через три дні вона вже сама збирає рюкзак до школи."]', 1, 1, 12) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 12), 1, 'Хто приходить до лікаря?', 'Аня', '["Оля","Катя","Даринка"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 12), 2, 'Що болить в Ані?', 'Горло', '["Нога","Голова","Рука"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 12), 3, 'Що лікар радить Ані пити?', 'Теплий чай', '["Холодний сік","Молоко","Каву"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 12), 4, 'Куди лікар радить Ані не йти завтра?', 'До школи', '["До магазину","До бабусі","До кафе"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 12), 5, 'Через скільки днів Ані має стати краще?', 'Через три дні', '["Через один день","Через тиждень","Через місяць"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 13, 'Мій вільний час', '["Після уроків я найбільше люблю ту годину, коли нікуди не треба поспішати. Мене звати Богдан. Спочатку я вечеряю і відпочиваю хвилин десять біля вікна. Потім вмикаю музику. Слухаю спокійні пісні, бо вони допомагають забути про втому.","Ще я часто малюю. У моєму зошиті є дерева, будинки, машини і люди на зупинці. Малюю я не дуже добре, але мені це подобається. На столі завжди лежать кольорові олівці і стара точилка. Іноді ввечері я дивлюся мультфільми з молодшим братом. Малюнки я складаю в стару папку.","Найбільше я люблю вихідні. У суботу зовсім не треба поспішати після школи. Можу довше малювати, слухати музику або просто сидіти біля вікна. У неділю ми всі разом п''ємо чай на кухні. Брат просить намалювати йому машину, і я малюю."]', 1, 1, 13) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 13), 1, 'Як звати хлопця в історії?', 'Богдан', '["Андрій","Назар","Олег"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 13), 2, 'Що Богдан спочатку робить після уроків?', 'Вечеряє і відпочиває', '["Біжить на ринок","Миє посуд","Іде до лікаря"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 13), 3, 'Які пісні слухає Богдан?', 'Спокійні пісні', '["Гучні пісні","Сумні пісні","Святкові пісні"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 13), 4, 'Що лежить на столі Богдана?', 'Олівці', '["Ключі","Квіти","Гроші"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 13), 5, 'З ким Богдан іноді дивиться мультфільми?', 'З молодшим братом', '["З бабусею","З учителькою","З сусідом"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 14, 'Дні тижня', '["У понеділок після школи я йду на тренування. Мене звати Катя, і мій тиждень має простий порядок. Там ми бігаємо, робимо вправи і вчимося працювати разом. Після цього я спокійно вечеряю вдома. Уроки роблю вже пізно ввечері.","У середу в мене знову тренування. Я вже знаю, що треба покласти в рюкзак: футболку, воду і рушник. Після заняття я трохи втомлена, але мені подобається рухатися.","У п''ятницю я зустрічаюся з друзями біля школи. Ми гуляємо, говоримо про уроки і сміємося з маленьких історій. Це приємний кінець навчального тижня.","У суботу я прибираю свою кімнату. Складаю книжки, витираю стіл і відкриваю вікно. Потім кімната стає світлою і чистою. Увечері я сідаю і думаю, що встигла за тиждень. У неділю я вже знаю, яким буде понеділок."]', 1, 1, 14) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 14), 1, 'Як звати дівчинку в історії?', 'Катя', '["Соня","Настя","Леся"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 14), 2, 'Що Катя робить у понеділок після школи?', 'Йде на тренування', '["Прибирає кімнату","Купує продукти","Малює листівку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 14), 3, 'Що Катя кладе в рюкзак у середу?', 'Футболку, воду і рушник', '["Книжку, ручку і зошит","Хліб, молоко і яблука","Квіти, стрічки і карту"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 14), 4, 'Коли Катя зустрічається з друзями?', 'У п''ятницю', '["У понеділок","У середу","У неділю"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 14), 5, 'Що Катя робить у суботу?', 'Прибирає свою кімнату', '["Йде до кафе","Відвідує лікаря","Їде автобусом"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 15, 'День пам''яті жертв Чорнобиля', '["На дошці написані дата і одне слово: Чорнобиль. Сьогодні двадцять шосте квітня, день пам''яті. Учителька говорить дітям про аварію на Чорнобильській станції. Вона пояснює простими словами, що це був важкий день для багатьох людей. Діти слухають уважно і майже не рухаються.","На столі стоять маленькі свічки. Учителька роздає їх дітям і показує, як тримати вогник рівно і безпечно. Діти обережно запалюють свічки одну від одної. У класі стає так тихо, що чути годинник. Потім усі мовчать одну хвилину. Ніхто не говорить, бо кожен розуміє, що це особливий момент.","Після уроку діти виходять у коридор і довго розмовляють пошепки. Один хлопчик каже, що вдома обов''язково розповість про урок бабусі. Учителька ставить свічки на підвіконня, і вони горять до кінця дня. Тепер діти знають, чому цей день тихий."]', 1, 1, 15) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 15), 1, 'Коли в школі проходить урок пам''яті?', 'Двадцять шостого квітня', '["Першого вересня","Двадцять другого січня","Восьмого березня"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 15), 2, 'Яке слово написане на дошці?', 'Чорнобиль', '["Київ","Великдень","Конституція"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 15), 3, 'Що стоїть на столі?', 'Маленькі свічки', '["Квіти для вчителів","Кошик із паскою","Чашки з чаєм"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 15), 4, 'Скільки часу всі мовчать?', 'Одну хвилину', '["Десять хвилин","Цілий урок","Три дні"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 15), 5, 'Що хлопчик хоче зробити вдома?', 'Розповісти про урок бабусі', '["Намалювати карту","Заспівати пісню","Купити свічку"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 16, 'Новий рік', '["Мене звати Тимко. Раніше, до 2022 року, Новий рік у нашій родині був дуже гучним. Тридцять першого грудня ми готували святковий стіл, а першого січня прокидалися пізніше. На столі були салат олів''є, мандарини, бутерброди і шампанське для дорослих. Ми не спали до півночі, вітали одне одного і дивилися у вікно на феєрверки. У дворі сміялися сусіди, а діти раділи кольоровим вогням.","Після початку повномасштабної війни наш Новий рік змінився. У місті стало менше гучних вечорів. Ми не запускаємо феєрверки, бо це може лякати людей і заважати спокою. Іноді ввечері буває повітряна тривога, тому ми слухаємо новини і тримаємо потрібні речі поруч. Молодша сестра питає, чому надворі так тихо. Батьки кажуть, що головне тепер — безпека і підтримка одне одного. Ми говоримо тихіше і частіше дякуємо за спокійний вечір.","Та Новий рік не зник із нашого дому. Ми однаково накриваємо стіл, чистимо мандарини і говоримо теплі слова. Мама ставить олів''є в гарну миску, а тато тихо відкриває шампанське для дорослих. Опівночі ми обіймаємося і бажаємо миру. Бабуся телефонує, а потім ми робимо сімейне фото біля маленької ялинки. Я дивлюся на родину і розумію: свято стало тихішим, але воно теж важливе. Я щасливий, що ми разом."]', 1, 1, 16) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 16), 1, 'Як звати хлопця в історії?', 'Тимко', '["Коля","Сашко","Петрик"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 16), 2, 'Яким був Новий рік у родині раніше?', 'Дуже гучним', '["Дуже тихим","Сумним","Коротким"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 16), 3, 'Що було на столі раніше?', 'Олів''є, мандарини і бутерброди', '["Борщ, хліб і сіль","Кутя, узвар і вареники","Піца і сік"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 16), 4, 'Чому родина тепер не запускає феєрверки?', 'Бо це може лякати людей', '["Бо немає снігу","Бо магазин закритий","Бо всі сплять удень"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 16), 5, 'Що родина бажає опівночі?', 'Миру', '["Грошей","Нової машини","Довгих канікул"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 17, 'День Соборності України', '["У класі на дошці висить велика карта України. Сьогодні двадцять друге січня, День Соборності. Біля карти лежать сині й жовті стрічки. Учителька показує карту дітям і каже, що цього дня країна згадує важливу подію.","Вона пояснює, що в 1919 році дві частини України об''єдналися. Для дітей це складна історія, тому вчителька говорить просто. Вона каже, що соборність означає єдність. Це коли люди з різних міст і сіл відчувають себе разом. Діти ставлять кілька запитань і слухають відповіді.","Потім діти беруться за руки і роблять у класі маленький ланцюг єдності. Стає весело і трохи гамірно. Вони називають міста: Київ, Львів, Харків, Одесу. Після цього діти прикріплюють стрічки до карти. Учителька киває і каже, що в Україні живе багато різних людей, але країна одна. Діти розуміють просту ідею: Україна — це один спільний дім."]', 1, 1, 17) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 17), 1, 'Коли говорять про День Соборності?', 'Двадцять другого січня', '["Двадцять восьмого червня","Двадцятого лютого","Двадцять п''ятого грудня"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 17), 2, 'Що висить на дошці в класі?', 'Карта України', '["Розклад уроків","Фото класу","Вишиванка"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 17), 3, 'Які стрічки лежать біля карти?', 'Сині й жовті', '["Чорні й червоні","Білі й зелені","Рожеві й сірі"]');
