INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 17), 5, 'Що діти роблять у класі?', 'Ланцюг єдності', '["Сніговика","Салат","Писанку"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 18, 'Різдво Христове', '["У нашій родині Різдво святкують двадцять п''ятого грудня. Бабуся пам''ятає, що раніше багато родин робили це сьомого січня. Мене звати Оленка, і я знаю цей день з дитинства. Це великий і теплий день в Україні. Зранку вдома тихо, але всі вже мають багато справ. Мама готує страви, тато ставить свічку на стіл, а я допомагаю складати серветки.","Увечері сім''я збирається за столом. Бабуся рахує: пісних страв має бути дванадцять, тобто без м''яса. На столі кутя, вареники і смажена риба. Свічка горить посеред столу до самого кінця вечері. Ми їмо повільно і говоримо спокійно.","Після вечері до нас приходять діти колядувати. Вони співають короткі колядки, а ми даємо їм цукерки і трохи грошей. Мені подобається слухати ці тонкі голоси біля дверей. Коли вони йдуть, у сінях ще довго пахне морозом."]', 1, 1, 18) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 18), 1, 'Коли родина Оленки святкує Різдво?', 'Двадцять п''ятого грудня', '["Сьомого березня","Першого вересня","Двадцять другого січня"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 18), 2, 'Що Оленка допомагає складати?', 'Серветки', '["Книжки","Квитки","Іграшки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 18), 3, 'Скільки пісних страв має бути на столі?', 'Дванадцять', '["Три","П''ять","Двадцять"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 18), 4, 'Яка страва є на столі?', 'Кутя', '["Піца","Шоколад","Салат олів''є"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 18), 5, 'Що родина дає дітям, які колядують?', 'Цукерки і трохи грошей', '["Книжки і ручки","Квіти і стрічки","Квитки і карту"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 19, 'День Героїв Небесної Сотні', '["Двадцятого лютого Настя йде з мамою до невеликого меморіалу в місті. Біля нього стоять квіти і свічки. Мама говорить тихо, бо це день пам''яті Героїв Небесної Сотні. Настя тримає маму за руку і дивиться на маленькі вогники. Вона бачить, що люди підходять повільно і не шумлять.","Настя питає маму: чому цих людей називають героями? Мама пояснює просто. Вона каже, що на Майдані були люди, які хотіли чесного і вільного життя для країни. Вони зробили важкий вибір, тому люди пам''ятають їх.","Настя кладе маленьку квітку біля свічок. Вона ще мала, але добре бачить повагу на обличчях дорослих. Поруч стоїть старша жінка і тихо поправляє стрічку на букеті. Мама бере Настю за руку і каже, що пам''ять допомагає людям бути добрішими і сильнішими. Настя ще раз озирається на свічки, перш ніж піти."]', 1, 1, 19) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 19), 1, 'Коли Настя йде з мамою до меморіалу?', 'Двадцятого лютого', '["Восьмого березня","Третього четверга травня","Першого січня"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 19), 2, 'Що стоїть біля меморіалу?', 'Квіти і свічки', '["Стіл і стільці","Санки і сніговик","Кошик і рушник"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 19), 3, 'Кого згадують цього дня?', 'Героїв Небесної Сотні', '["Учителів","Лікарів","Першокласників"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 19), 4, 'Що Настя кладе біля свічок?', 'Маленьку квітку', '["Синю стрічку","Листівку","Книжку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 19), 5, 'Що, за словами мами, допомагає людям бути добрішими і сильнішими?', 'Пам''ять', '["Гучна музика","Швидка дорога","Нова іграшка"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 20, 'Міжнародний жіночий день', '["Восьмого березня я прокидаюся раніше, ніж зазвичай. Мене звати Сашко, і сьогодні я хочу привітати маму. Тато тихо допомагає мені знайти вазу і чистий конверт. У домі ще темно, і ми з татом говоримо пошепки.","Квіти я купив учора і сховав їх у себе в кімнаті. Це невеликий букет, але я вибирав його дуже довго. Листівку я підписав пізно ввечері, коли всі вже спали. Усередині написано: «Мамо, ти найкраща». Я довго старався, щоб букви вийшли рівні й гарні.","Коли мама заходить на кухню, я даю їй квіти і підписану листівку. Вона читає мої слова, усміхається і міцно обіймає мене. Мені трохи соромно, але дуже приємно. Тато теж усміхається і ставить букет у вазу біля вікна. Мама каже, що це найкращий подарунок для неї."]', 1, 1, 20) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 20), 1, 'Кого Сашко хоче привітати восьмого березня?', 'Маму', '["Бабусю","Учительку","Сестру"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 20), 2, 'Що тато допомагає знайти?', 'Вазу і чистий конверт', '["Рюкзак і зошит","Квиток і гроші","Куртку і шарф"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 20), 3, 'Що Сашко купує біля будинку?', 'Невеликий букет', '["Яблучний сік","Теплий хліб","Нову книжку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 20), 4, 'Що Сашко дарує мамі?', 'Квіти і підписану листівку', '["Книжку і цукерки","Торт і кулю","Малюнок і м''яч"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 20), 5, 'Що мама робить, коли читає слова Сашка?', 'Усміхається і обіймає його', '["Одразу йде на роботу","Пише список покупок","Відчиняє вікно"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 21, 'Вишиванка — мій одяг', '["Сьогодні в школі свято, тому я вдягаю свою вишиванку. Мене звати Даринка, і ця сорочка в мене вже два роки. Вона біла, легка і дуже приємна на дотик. На рукавах є червоний орнамент. Я обережно застібаю ґудзики, розчісую волосся і дивлюся в дзеркало.","Мама заходить до кімнати і усміхається. Вона каже, що моя вишиванка дуже красива. Я трохи червонію, бо мені приємно це чути. Потім мама поправляє комір і просить не забути рюкзак. У коридорі вже чекає молодший брат. У школі багато дітей теж приходять у вишиванках.","У класі світло і святково. Ми робимо фото біля дошки і довго вибираємо, хто де стане. Подруга питає, чи зручна моя сорочка, і я кажу, що дуже. Увечері я вішаю вишиванку на плічка, щоб вона не пом''ялася до наступного свята."]', 1, 1, 21) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 21), 1, 'Як звати дівчинку в історії?', 'Даринка', '["Оленка","Софійка","Іринка"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 21), 2, 'Що Даринка вдягає в школу?', 'Вишиванку', '["Теплу куртку","Святкову сукню","Спортивну форму"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 21), 3, 'Який орнамент є на рукавах?', 'Червоний орнамент', '["Синій орнамент","Зелений орнамент","Чорний орнамент"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 21), 4, 'Що мама поправляє Даринці?', 'Комір', '["Рюкзак","Шапку","Рукавиці"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 21), 5, 'Де клас робить фото?', 'Біля дошки', '["Біля магазину","У парку","На ринку"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 22, 'Борщ — улюблена страва', '["Щосуботи моя бабуся готує великий борщ. Зранку в хаті вже тепло і смачно пахне овочами. Я сиджу біля столу і дивлюся, як бабуся дістає овочі. Вона бере буряк, картоплю, капусту і квасолю. Від нього борщ стає яскраво-червоним.","Бабуся працює повільно. Вона каже, що добрий борщ не любить поспіху. Я допомагаю подати тарілки, ложки і хліб. Мені цікаво, як прості овочі стають такою смачною стравою. Різати я ще не вмію, тому просто дивлюся і питаю.","Коли борщ готовий, уся сім''я сідає за стіл. Ми їмо його зі сметаною і свіжим чорним хлібом. Тато просить добавки, а мама сміється і накладає йому ще одну повну миску. Бабуся радіє, коли всім смачно. Ми довго говоримо за столом і нікуди не йдемо. Ніхто не встає з-за столу першим."]', 1, 1, 22) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 22), 1, 'Коли бабуся готує борщ?', 'Щосуботи', '["Щопонеділка","Щовечора","Тільки на Різдво"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 22), 2, 'Який овоч робить борщ червоним?', 'Буряк', '["Огірок","Картопля","Капуста"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 22), 3, 'Що допомагає подати оповідач?', 'Тарілки і ложки', '["Квіти і вазу","Квитки і гроші","Свічки і стрічки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 22), 4, 'З чим сім''я їсть борщ?', 'Зі сметаною і свіжим хлібом', '["З яблучним соком","З мандаринами","З шоколадом"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 22), 5, 'Яким є суботній борщ для родини?', 'Теплим сімейним обідом', '["Шкільним завданням","Спортивним заняттям","Довгою дорогою"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 23, 'Великдень', '["На Великдень наша сім''я встає ще затемна. Надворі тихо, але вдома вже світиться кухня. Мене звати Оля, і цей ранок я чекаю цілий рік. Мама перевіряє кошик, а тато бере чистий рушник. У кошику лежать паска, крашанки і ковбаса. Я несу маленьку свічку і йду поруч із мамою.","Ми йдемо до церкви повільно, бо ранок прохолодний. Біля входу стоять інші родини з кошиками. Після служби люди усміхаються, обіймаються і кажуть: «Христос Воскрес!» Я теж повторюю ці слова і міцніше тримаю маму за теплу руку.","Коли ми повертаємося додому, на столі вже чекають тарілки. Я вибираю найяскравішу крашанку. Родина сідає разом, і в кімнаті стає тепло від розмов. Бабуся розрізає паску, а я допомагаю подати чай. Ми стукаємося крашанками, і моя витримує найдовше з усіх."]', 1, 1, 23) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 23), 1, 'Коли сім''я Олі встає на Великдень?', 'Дуже рано', '["Опівночі","Після обіду","Пізно ввечері"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 23), 2, 'Що лежить у кошику?', 'Паска, крашанки і ковбаса', '["Піца, сік і шоколад","Книжки, ручки і зошити","Квіти, стрічки і карта"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 23), 3, 'Куди родина йде вранці?', 'До церкви', '["До школи","До кафе","На ферму"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 23), 4, 'Що люди кажуть після служби?', 'Христос Воскрес!', '["Добрий вечір!","З Новим роком!","Смачного!"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 23), 5, 'Що бабуся розрізає вдома?', 'Паску', '["Піцу","Хліб із сіллю","Шоколадку"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 24, 'Вареники на обід', '["У неділю я приходжу до бабусі на обід. На кухні пахне свіжим тістом, а на столі лежить білий рушник. Удома мене звуть Марійкою, а бабуся — Марічкою. Сьогодні вона робить вареники з картоплею. Я дуже люблю цю страву і відразу біжу мити руки.","Бабуся показує мені, як обережно тримати вареник у руках. Вона довіряє мені тільки просту роботу, зате вчить бути уважною. Я кладу готові вареники на тарілку і стежу, щоб вони не торкалися. Тісто на пальцях швидко висихає і стає зовсім білим. Бабуся сміється і показує, як його змити.","Коли обід готовий, бабуся подає вареники зі смаженою цибулею. Вони м''які і дуже смачні. Ми їмо разом і довго говоримо про школу і сусідів. Вона каже, що наступного разу навчить мене ще краще."]', 1, 1, 24) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 24), 1, 'До кого Марійка приходить у неділю?', 'До бабусі', '["До лікаря","До вчительки","До подруги"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 24), 2, 'Які вареники робить бабуся?', 'З картоплею', '["З вишнями","З сиром","З капустою"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 24), 3, 'Що Марійка робить перед допомогою?', 'Миє руки', '["П''є чай","Відкриває вікно","Пише лист"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 24), 4, 'З чим бабуся подає вареники?', 'Зі смаженою цибулею', '["З медом","З морозивом","З мандаринами"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 24), 5, 'Що бабуся обіцяє Марійці?', 'Навчити її ще краще', '["Купити нову книжку","Приїхати в гості","Дати рецепт"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 25, 'Хліб та сіль', '["Бабуся Олена чекає гостей разом зі своєю маленькою онукою Софійкою. На столі лежить вишитий рушник. На ньому — круглий хліб і маленька сільниця. У кімнаті чисто, і біля дверей уже стоять готові капці. Софійка дивиться на стіл і питає, чому хліб лежить так красиво.","Бабуся пояснює, що в Україні гостей часто зустрічають хлібом і сіллю. Вона каже, що це давній знак поваги і гостинності. Коли людина вперше приходить у дім, господарі показують, що раді її бачити. Софійка слухає уважно і киває.","Скоро гості заходять до хати. Софійка допомагає бабусі подати гостям хліб і сіль. Вона бачить, як люди усміхаються і тихо дякують. Потім усі сідають за стіл і починають довгу розмову. Тепер дівчинка знає, навіщо хліб цілий ранок чекав гостей на рушнику."]', 1, 1, 25) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 25), 1, 'Хто чекає гостей із Софійкою?', 'Бабуся Олена', '["Мама Оля","Тітка Катя","Учителька"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 25), 2, 'Що лежить на вишитому рушнику?', 'Круглий хліб', '["Маленька писанка","Білий аркуш","Шкільний зошит"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 25), 3, 'Що стоїть біля хліба?', 'Маленька сільниця', '["Ваза з квітами","Чашка чаю","Свічка"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 25), 4, 'Що означає хліб і сіль?', 'Повагу і гостинність', '["Швидку дорогу","Тихий урок","Нову роботу"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 25), 5, 'Що Софійка допомагає подати гостям?', 'Хліб і сіль', '["Сік і печиво","Борщ і сметану","Квіти і листівку"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 26, 'Моя вулиця', '["Машини на нашій вулиці їдуть повільно, наче нікуди не поспішають. Мене звати Леся, і вулиця в нас довга і тиха. Уздовж дороги стоять невеликі будинки з тихими садами. Уранці я бачу, як сусіди йдуть на роботу, а діти несуть рюкзаки до школи. Потім усе знову стихає.","Біля нашого будинку є маленький парк. У ньому ростуть кілька старих дерев і стоять дві лавки. Поруч є дитячий майданчик із гойдалками і гіркою. Після уроків я часто проходжу повз нього і бачу знайомих дітей.","Щовечора після вечері діти граються на майданчику. Хтось катається на гойдалці, хтось бігає або малює крейдою на доріжці. Дорослі сидять на лавках і тихо розмовляють. Увечері тут чути сміх і далекий гавкіт собак. Я знаю тут кожне дерево і кожну лавку біля дому."]', 1, 1, 26) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 26), 1, 'Як звати оповідачку?', 'Леся', '["Дарина","Настя","Олена"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 26), 2, 'На якій вулиці живе Леся?', 'На довгій і тихій', '["На короткій і гучній","На широкій і шумній","На новій і темній"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 26), 3, 'Що є біля будинку Лесі?', 'Маленький парк', '["Великий ринок","Нова школа","Гучний вокзал"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 26), 4, 'Скільки лавок стоїть у парку?', 'Дві лавки', '["Одна лавка","Три лавки","Десять лавок"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 26), 5, 'Що Леся знає на своїй вулиці?', 'Кожне дерево і кожну лавку', '["Назви всіх машин","Усі магазини міста","Розклад автобусів"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 27, 'Перший дзвоник — День знань', '["Першого вересня біля школи дуже людно. Це День знань, і новий навчальний рік починається урочисто. Учні приходять у чистому одязі, тримають квіти для вчителів і шукають свої класи. Батьки роблять фото і тихо бажають дітям успіху.","Найбільше хвилюються першокласники. Вони вперше заходять до школи з великими рюкзаками. Деякі діти тримають батьків за руку, а інші сміливо дивляться на двері. Біля них стоять старші учні і допомагають знайти клас.","Учителька вітає всіх і просить дітей стати ближче. Потім старша учениця піднімає маленький дзвоник над головою. Він дзвенить голосно і коротко, і всі плескають у долоні.","Після цього діти заходять до класів. У коридорі пахне квітами і новими зошитами. Першокласники трохи мовчать, але скоро усміхаються. Учителька каже, що кожен день принесе нові знання. Двері класів зачиняються одні за одними, і в коридорі стає тихо."]', 1, 1, 27) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 27), 1, 'Коли біля школи дуже людно?', 'Першого вересня', '["Двадцять п''ятого грудня","Восьмого березня","У другу неділю травня"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 27), 2, 'Що учні тримають для вчителів?', 'Квіти', '["Свічки","Квитки","Подарунки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 27), 3, 'Хто найбільше хвилюється?', 'Першокласники', '["Продавці","Лікарі","Сусіди"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 27), 4, 'Хто тримає маленький дзвоник?', 'Старша учениця', '["Мама","Першокласник","Офіціантка"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 27), 5, 'Чим пахне в коридорі?', 'Квітами і новими зошитами', '["Кавою і випічкою","Снігом і морозом","Борщем і хлібом"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 28, 'Покупки на ринку', '["У неділю тато йде на ринок. Він бере велику торбу і список покупок. Ринок уже відкритий, і між довгими рядами ходить багато людей. На столах лежать овочі, фрукти і зелень. Мама просила вибрати все найкраще. Тато хоче купити продукти для недільного обіду.","Біля одного столу він бачить свіжі помідори і зелені огірки. Продавець вітається і показує йому найкращі овочі. Тато бере помідори, огірки і пучок кропу з петрушкою. Він уважно перевіряє все, бо вдома цього вже не виправиш. Продавець усміхається і дає йому маленьку знижку.","Тато дякує, платить і кладе покупки в торбу. Він не затримується довго, бо вдома чекає родина. Дорогою він думає про салат і теплий суп, який сьогодні зварить мама. Скоро тато повертається додому зі свіжими продуктами і гарним настроєм."]', 1, 1, 28) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 28), 1, 'Коли тато йде на ринок?', 'У неділю', '["У понеділок","У середу","У п''ятницю"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 28), 2, 'Що тато бере з собою?', 'Велику торбу і список', '["Рюкзак і рушник","Квіти і конверт","Свічку і кошик"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 28), 3, 'Що лежить на столах на ринку?', 'Овочі, фрукти і зелень', '["Книжки і зошити","Квіти і свічки","Одяг і взуття"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 28), 4, 'Які овочі тато бере?', 'Помідори й огірки', '["Буряк і картоплю","Моркву і капусту","Гриби і квасолю"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 28), 5, 'Про що тато думає дорогою додому?', 'Про салат і теплий суп', '["Про урок музики","Про автобусний квиток","Про перший дзвоник"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 29, 'Я допомагаю вдома', '["Щовечора після вечері я мию посуд. Мене звати Артем, і це моя робота вже давно. Спочатку ставлю тарілки біля раковини, потім мию їх теплою водою. Витираю все рушником і складаю посуд у шафу. Молодша сестра іноді подає мені чисті чашки.","У суботу я прибираю кімнати пилососом. Мені не завжди хочеться це робити, але я знаю, що так вдома стає чистіше. Починаю зі своєї кімнати, а потім переходжу до коридору. Мама поруч готує обід. Пилосос гуде так голосно, що ми не чуємо одне одного.","Коли я закінчую, мама дякує мені. Вона каже, що моя допомога справді важлива. Потім ми разом обідаємо у чистій світлій кухні. Сестра ставить на стіл вазу з польовими квітами. Я сідаю останнім і бачу, що все на своєму місці."]', 1, 1, 29) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 29), 1, 'Як звати хлопця в історії?', 'Артем', '["Олег","Тимко","Богдан"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 29), 2, 'Що Артем робить щовечора після вечері?', 'Миє посуд', '["Готує борщ","Йде на тренування","Читає книжку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 29), 3, 'Чим Артем миє тарілки?', 'Теплою водою', '["Холодним соком","Молоком","Фарбою"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 29), 4, 'Що Артем прибирає пилососом у суботу?', 'Кімнати', '["Сад","Магазин","Клас"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 29), 5, 'Що мама каже про допомогу Артема?', 'Що вона справді важлива', '["Що вона зайва","Що вона запізніла","Що вона легка"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 30, 'День матері', '["День матері приходить у другу неділю травня. Мене звати Коля, і подарунок я почав готувати ще в суботу. Купувати щось дороге я не хотів. Увечері я взяв білий аркуш, олівці і сів за письмовий стіл. У кімнаті було зовсім тихо, тому думалося легко.","На листівці я намалював квіти, сонце і наш маленький будинок. Слова написав усередині, великими рівними літерами: «Мамо, я тебе люблю». Тато порадив підписати дату, і я зробив це дуже уважно. Потім я сховав листівку під подушку до ранку.","У неділю зранку я мовчки дав листівку мамі. Вона прочитала, усміхнулася і раптом заплакала від радості. Потім мама обійняла мене і повісила листівку на холодильник біля сімейного фото. Вона довго дивилася на неї і нічого не казала. Листівка висить там і досі."]', 1, 1, 30) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 30), 1, 'Коли приходить День матері?', 'У другу неділю травня', '["У третій четвер травня","Першого вересня","Двадцятого лютого"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 30), 2, 'Який подарунок Коля хоче зробити мамі?', 'Листівку своїми руками', '["Дорогий телефон","Новий велосипед","Велику сумку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 30), 3, 'Що Коля бере в суботу ввечері?', 'Білий аркуш і олівці', '["Кошик і рушник","Квиток і гроші","Футболку і воду"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 30), 4, 'Що Коля пише всередині листівки?', 'Мамо, я тебе люблю', '["Мамо, купи піцу","Я йду до школи","Сьогодні холодно"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 30), 5, 'Куди мама вішає листівку?', 'На холодильник', '["На двері класу","На карту України","На вікно"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 31, 'День вишиванки', '["У третій четвер травня в школі святкують День вишиванки. Мене звати Остап, і цей день я чекаю щороку. Зранку я вдягаю білу сорочку з синім орнаментом. Мама каже, що її колись вишила моя бабуся.","Коли я приходжу до школи, бачу багато кольорів. Уся школа сьогодні у вишиванках. Учні стоять у коридорах, вітаються і показують одне одному свої сорочки. Навіть учителі приходять у вишитих сорочках.","На великій перерві наш клас робить фото біля вікна. Потім ми говоримо про родинні орнаменти. Один хлопчик каже, що на його сорочці є чорні й червоні нитки. Дівчинка показує стару вишиванку своєї мами.","Після уроків я акуратно складаю сорочку в рюкзак. Мені подобається, що цього дня всі одягнені по-різному, але почуваються разом. Дорогою додому я думаю про бабусю, яка шила цю сорочку. Удома я вішаю її поруч із маминою."]', 1, 1, 31) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 31), 1, 'Як звати хлопця в історії?', 'Остап', '["Рома","Олег","Петрик"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 31), 2, 'Коли в школі святкують День вишиванки?', 'У третій четвер травня', '["У другу неділю травня","Першого вересня","Двадцять четвертого серпня"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 31), 3, 'Яку сорочку Назар вдягає зранку?', 'Білу сорочку з синім орнаментом', '["Чорну сорочку з червоним орнаментом","Зелену сорочку без орнаменту","Жовту футболку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 31), 4, 'Де клас робить фото на великій перерві?', 'Біля вікна', '["Біля магазину","На площі","У дворі"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 31), 5, 'Про кого Назар думає дорогою додому?', 'Про бабусю і клас', '["Про лікаря і маму","Про ринок і продавця","Про море і готель"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 32, 'У кафе', '["Рома і Юля зустрічаються після уроків біля маленького кафе. Надворі прохолодно і сіро, тому вони швидко заходять усередину. Усередині тепло, пахне кавою і свіжою випічкою. Друзі сідають біля вікна, де видно тиху вулицю. Вони кладуть рюкзаки під стіл і знімають шапки.","Офіціантка підходить до їхнього столика. Рома замовляє каву, бо хоче трохи зігрітися. Юлі більше хочеться яблучного соку і маленького печива. Вони не дивляться довго на меню, бо прийшли просто поговорити після довгого дня. Офіціантка приносить усе досить швидко.","Рома розповідає про смішний випадок на уроці, а Юля сміється. Потім вони довго говорять про домашнє завдання і плани на вихідні. Час минає швидко. За вікном темніє, і на вулиці одна за одною вмикаються ліхтарі. Виходять вони останніми, уже майже перед закриттям."]', 1, 1, 32) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 32), 1, 'Де Рома і Юля зустрічаються після уроків?', 'Біля маленького кафе', '["Біля школи","На ринку","У парку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 32), 2, 'Чому друзі швидко заходять усередину?', 'Бо надворі прохолодно', '["Бо почався урок","Бо вони поспішають на автобус","Бо кафе зачиняється"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 32), 3, 'Що замовляє Рома?', 'Каву', '["Яблучний сік","Чай","Морозиво"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 32), 4, 'Що замовляє Юля?', 'Яблучний сік і печиво', '["Каву і торт","Борщ і хліб","Піцу і чай"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 32), 5, 'Про що друзі говорять у кафе?', 'Про домашнє завдання і плани', '["Про лікаря і ліки","Про ринок і овочі","Про ферму і тварин"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 33, 'Моя улюблена їжа', '["Найбільше з усього на світі я люблю піцу. Мене звати Петрик, і в їжі я не дуже вибагливий. Мені подобається тонке тісто, гарячий сир і теплий соус. Коли тато приносить піцу додому, я відразу біжу на кухню і допомагаю ставити тарілки. Я завжди вибираю шматок, де найбільше сиру і соусу.","Моя бабуся сміється і каже, що вареники набагато смачніші. Вона робить їх з картоплею або з домашнім сиром. Я не сперечаюся з бабусею, бо її страва справді дуже добра. Тісто м''яке і тепле.","Тепер я думаю, що обидві страви чудові кожна по-своєму. Піцу я люблю їсти з друзями, а вареники — тільки з бабусею. Коли ми сидимо разом за столом, їжа здається значно смачнішою. Бабуся розповідає смішні історії, а я слухаю і зовсім забуваю жувати."]', 1, 1, 33) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 33), 1, 'Як звати хлопця в історії?', 'Петрик', '["Данило","Артем","Микола"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 33), 2, 'Яку їжу Петрик любить найбільше?', 'Піцу', '["Борщ","Кашу","Пампушки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 33), 3, 'Який шматок піци Петрик завжди вибирає?', 'Де найбільше сиру', '["Де немає соусу","Найменший шматок","Найхолодніший шматок"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 33), 4, 'Які вареники робить бабуся?', 'З картоплею або сиром', '["З м''ясом або грибами","З вишнями або маком","З капустою або рибою"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 33), 5, 'З ким Петрик любить їсти вареники?', 'З бабусею', '["З друзями","З учителькою","З сусідами"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 34, 'Зима в Україні', '["Узимку в Україні часто лежить сніг. Ранок буває дуже холодним, але вулиці виглядають світлими і тихими. Дерева стоять білі. На дахах будинків теж лежить сніг, і місто здається зовсім новим і тихим. Діти після школи виходять у двір і ліплять сніговиків. У парках вони катаються на санчатах з невеликих гірок. Іноді батьки теж виходять надвір і допомагають дітям будувати гірку.","Дорослі вдягають теплі куртки, шапки і товсті рукавиці. Увечері вікна світяться, а вдома пахне чаєм і мандаринами. Найкраще зимове свято для багатьох людей — Новий рік. Родини збираються разом, вітають одне одного і згадують минулий рік. Діти чекають подарунків і довго не лягають спати. Надворі мороз, а в кімнатах тепло і світло від ялинкових гірлянд. Зима холодна, але вона може бути дуже радісною."]', 1, 1, 34) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 34), 1, 'Що часто лежить в Україні взимку?', 'Сніг', '["Пісок","Листя","Квіти"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 34), 2, 'Що діти роблять після школи у дворі?', 'Роблять сніговиків', '["Садять дерева","Купують хліб","Пишуть листи"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 34), 3, 'На чому діти катаються в парках?', 'На санчатах', '["На велосипедах","На човнах","На автобусах"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 34), 4, 'Що вдягають дорослі взимку?', 'Теплі куртки, шапки і рукавиці', '["Футболки і шорти","Легкі сукні","Костюми для плавання"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 34), 5, 'Яке зимове свято назване найкращим для багатьох людей?', 'Новий рік', '["Великдень","День знань","День матері"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 35, 'Писанка — мистецтво розпису яєць', '["Перед Великоднем я приходжу до бабусі і бачу на столі яйця та фарби. Мене звати Дарина, і сьогодні я вчуся писати писанку. Біля вікна лежать серветки і тонкий олівець. Бабуся каже, що писанка — це не просто кольорове яйце. Це маленький предмет мистецтва. Я сідаю поруч і дуже хочу спробувати.","Бабуся показує мені прості знаки. Сонце означає світло, квітка нагадує про весну, а хвиля схожа на воду. Більше знаків вона поки не показує. Я обережно малюю тонкі лінії і стараюся не поспішати. Коли рука тремтить, бабуся спокійно підтримує мене.","Моя перша писанка виходить не зовсім рівною, але я радію. На ній є маленьке сонце, квітка і синя хвиля. Бабуся каже, що головне — робити все з увагою. Вона ставить її на серветку біля вікна, щоб фарба висохла. Проти світла синя хвиля здається майже прозорою."]', 1, 1, 35) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 35), 1, 'Коли Дарина приходить до бабусі?', 'Перед Великоднем', '["Після Нового року","Першого вересня","У середині літа"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 35), 2, 'Що лежить на столі?', 'Чисті яйця та фарби', '["Книжки та зошити","Помідори та огірки","Квіти та свічки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 35), 3, 'Що означає сонце на писанці?', 'Світло', '["Воду","Весну","Дорогу"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 35), 4, 'Що є на першій писанці Дарини?', 'Сонце, квітка і синя хвиля', '["Прапор, серце і хата","Дерево, річка і міст","Кіт, м''яч і книга"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 35), 5, 'Що бабуся каже про головне в роботі?', 'Робити все з увагою', '["Поспішати","Малювати тільки червоним","Не дивитися на яйце"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 36, 'Числа і гроші', '["Олег іде до маленького магазину біля дому. У кишені він має гроші, а в руці тримає короткий список. Мама просила купити сік і шоколад. Олег уважно дивиться на полицю, бо хоче вибрати правильно і не помилитися. Магазин невеликий, і продавчиня знає його в обличчя.","Пляшка яблучного соку коштує двадцять гривень. Невелика шоколадка коштує п''ятнадцять гривень. Олег не поспішає і кладе обидві речі в кошик. Ще раз дивиться на цінники, щоб бути впевненим. Біля каси він вітається з продавчинею і ставить покупки на стіл.","Вона називає суму, і Олег платить готівкою. Вона дає йому решту і чек. Олег кладе все в пакет, але не йде одразу. Спочатку він перевіряє сік, шоколад і решту. Усе правильно. Потім Олег дякує, усміхається і виходить із магазину."]', 1, 1, 36) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 36), 1, 'Куди йде Олег?', 'До маленького магазину', '["До школи","До лікаря","На ферму"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 36), 2, 'Що мама просить купити?', 'Сік і шоколад', '["Хліб і молоко","Піцу і сир","Квіти і вазу"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 36), 3, 'Скільки коштує пляшка яблучного соку?', 'Двадцять гривень', '["П''ятнадцять гривень","Дев''ять гривень","Тридцять гривень"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 36), 4, 'Як Олег платить?', 'Готівкою', '["Карткою","Чеком","Квитком"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 36), 5, 'Що Олег перевіряє перед виходом?', 'Сік, шоколад і решту', '["Ключі, куртку і шапку","Книжку, ручку і зошит","Паску, яйця і свічку"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 37, 'Моя мама', '["Моя мама працює медсестрою. Вона прокидається дуже рано, коли в квартирі ще тихо. Мене звати Настя, і я рідко бачу її вранці. Мама швидко п''є чай, бере сумку і перевіряє, чи має ключі. Я іноді прокидаюся і бачу її вже біля дверей.","Увечері мама повертається додому втомлена. Вона знімає пальто, миє руки і сідає на кухні. Я майже нічого не питаю про роботу, бо знаю, що їй потрібен спокій. Замість цього я ставлю їй чашку теплого чаю.","Потім мама завжди обіймає мене. Навіть коли вона дуже втомлена, її обійми теплі і добрі. Ми трохи говоримо про мій день, уроки і подруг. Перед сном вона бажає мені доброї ночі і гасить світло. Уранці все почнеться спочатку, і я знаю, що чашка чаю чекатиме на неї знову."]', 1, 1, 37) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 37), 1, 'Як звати оповідачку?', 'Настя', '["Іринка","Софія","Катруся"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 37), 2, 'Ким працює мама Насті?', 'Медсестрою', '["Учителькою","Продавчинею","Офіціанткою"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 37), 3, 'Коли мама прокидається?', 'Дуже рано', '["Після обіду","Опівночі","Пізно ввечері"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 37), 4, 'Що Настя ставить мамі ввечері?', 'Чашку теплого чаю', '["Тарілку борщу","Склянку холодного соку","Кошик із паскою"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 37), 5, 'Що Настя робить для мами ввечері?', 'Ставить їй чашку теплого чаю', '["Готує вечерю","Прибирає кімнату","Читає їй книжку"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 38, 'Пісня на уроці', '["Сьогодні в нас урок музики. Учителька заходить до класу і відкриває старе піаніно. Мене звати Олена, і музику я люблю найбільше. На дошці вона пише тему сьогоднішнього заняття. Вона каже, що сьогодні ми будемо вчити стару народну пісню. Її назва — «Ой, у лузі червона калина».","Спочатку ми слухаємо мелодію. Учителька грає на піаніно повільно, щоб усі добре зрозуміли ритм. Потім вона просить нас сидіти рівно і дихати спокійно. Деякі слова складні, але ми повторюємо їх разом без поспіху. Мені допомагає подруга за партою.","Після кількох спроб клас співає краще. Я чую голоси друзів навколо і стараюся не збиватися. Учителька усміхається і знову починає грати спочатку. На останніх хвилинах уже ніхто не соромиться. Наприкінці ми співаємо всі разом, і піаніно вже ледве чути за голосами."]', 1, 1, 38) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 38), 1, 'Який урок сьогодні в Олени?', 'Урок музики', '["Урок математики","Урок малювання","Урок історії"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 38), 2, 'Яку пісню вчить клас?', 'Ой, у лузі червона калина', '["Щедрик","Несе Галя воду","Червона рута"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 38), 3, 'На чому грає учителька?', 'На піаніно', '["На гітарі","На скрипці","На барабані"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 38), 4, 'Що допомагає Олені?', 'Подруга за партою', '["Молодший брат","Бабуся","Продавчиня"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 38), 5, 'Що змінюється на останніх хвилинах уроку?', 'Ніхто вже не соромиться', '["Усі мовчать","Усі втомлюються","Учителька сердиться"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 39, 'Тварини на фермі', '["Улітку я часто їжджу до дідуся на ферму. Мене звати Петрик, і тут я вже не гість. Там є корови, кури і свині. Я не боюся тварин, але завжди слухаю дідуся. Він каже, що на фермі треба бути спокійним і уважним.","Уранці всіх тварин треба годувати. Дідусь несе корм для свиней, а я допомагаю йому тримати відро. Потім ми даємо зерно курям. Корови стоять біля хліва і чекають на свою їжу. Я бачу, що кожна тварина має свій час.","Після роботи ми з дідусем сідаємо біля будинку і п''ємо воду. Він дякує мені за допомогу і каже, що я вже добре знаю ранкові справи. Руки пахнуть сіном, і я весь мокрий від роботи. Завтра вранці все почнеться знову, і я вже знаю кожен крок."]', 1, 1, 39) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 39), 1, 'До кого Петрик часто їздить улітку?', 'До дідуся на ферму', '["До бабусі в місто","До друга в школу","До лікаря"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 39), 2, 'Які тварини є на фермі?', 'Корови, кури і свині', '["Коти, собаки і коні","Качки, гуси і кози","Риби, птахи і зайці"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 39), 3, 'Що дідусь несе для свиней?', 'Корм', '["Воду","Сіно","Зерно"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 39), 4, 'Що Петрик допомагає тримати?', 'Відро', '["Рушник","Кошик","Прапор"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 39), 5, 'Що дідусь каже Петрикові?', 'Що він уже добре знає ранкові справи', '["Що йому час додому","Що робота закінчена","Що завтра можна не приходити"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 40, 'Хто де живе', '["Я живу в місті, де багато будинків, магазинів і автобусів. Мене звати Софія, і я знаю тут кожен двір. Мені подобається, що школа близько, а після уроків можна піти до бібліотеки. У місті завжди є що робити.","Моя бабуся живе в селі, і я відвідую її влітку. Там тихі ранки, широке небо і мало машин. Біля села є річка, куди ми ходимо гуляти після обіду. У бабусі також є великий сад з яблунями і квітами. Уранці там чути тільки птахів і далекий трактор.","Я не порівнюю місто і село. Вони просто різні. У місті я вчуся і бачу друзів, а в селі відпочиваю. Увечері ми з бабусею сидимо в саду і п''ємо чай. Яблуня над нами вже зовсім стара і скрипить від вітру."]', 1, 1, 40) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 40), 1, 'Де живе Софія?', 'У місті', '["У селі","У горах","Біля моря"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 40), 2, 'Куди Софія може піти після уроків у місті?', 'До бібліотеки', '["До річки або саду","На ферму або ринок","До лікаря або аптеки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 40), 3, 'Де живе бабуся Софії?', 'У селі', '["У місті","У Києві","В Одесі"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 40), 4, 'Що є біля села?', 'Річка', '["Метро","Великий вокзал","Море"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 40), 5, 'Де Софія з бабусею п''є чай увечері?', 'У саду', '["У кафе","У школі","На автобусній зупинці"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 41, 'День Конституції України', '["Учителька кладе на стіл невелику книжку в синій обкладинці. Сьогодні двадцять восьме червня, День Конституції. Вона каже, що Конституція — це головний закон нашої країни. У класі тихо, бо тема звучить серйозно і незвично. Але вчителька говорить дуже просто і спокійно.","Вона пояснює, що громадяни мають права. Наприклад, право вчитися і вільно говорити свою думку. Але в кожного є ще й обов''язки. Треба поважати інших, берегти країну і не заважати людям поруч себе. Один учень раптом питає, чи це схоже на правила класу.","Потім учні самі наводять прості приклади зі школи. Клас має бути безпечним. І кожен повинен не заважати іншим. Учителька погоджується і каже, що це дуже хороший приклад. Наприкінці уроку діти розуміють головну ідею: права і обов''язки завжди йдуть разом."]', 1, 1, 41) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 41), 1, 'Коли в школі говорять про День Конституції України?', 'Двадцять восьмого червня', '["Двадцять четвертого серпня","Першого жовтня","У четверту суботу листопада"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 41), 2, 'Що показує дітям учителька?', 'Невелику книжку', '["Карту міста","Стару вишиванку","Кошик із паскою"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 41), 3, 'Що таке Конституція за словами вчительки?', 'Головний закон країни', '["Шкільний розклад","Святкова пісня","Родинний альбом"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 41), 4, 'Яке право називає вчителька?', 'Право вчитися', '["Право шуміти","Право запізнюватися","Право не слухати інших"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 41), 5, 'Яку головну ідею розуміють діти?', 'Права і обов''язки йдуть разом', '["Свято має бути гучним","Уроки не потрібні","Кожен день однаковий"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 42, 'Дорога до школи', '["Я щодня ходжу до школи пішки. Мене звати Іринка, і дорога займає приблизно десять хвилин. Після сніданку я беру рюкзак і закриваю двері великим ключем. Мама махає мені з вікна. Я махаю у відповідь і повертаю за ріг біля аптеки.","Спочатку я проходжу повз невеликий тихий парк. Там ростуть старі дерева, а біля доріжки стоїть зелена дерев''яна лавка. Восени під ними завжди повно жовтого сухого листя. Потім я йду повз магазин, де вранці вже купують свіжий теплий хліб. Я вітаюся із сусідкою, якщо бачу її біля входу.","Далі дорога веде прямо до школи. Я ніколи не поспішаю, бо добре знаю свій час. Біля воріт уже стоять кілька моїх однокласників. Ми вітаємося і разом заходимо всередину. У роздягальні я спокійно вішаю куртку і чую перший дзвінок."]', 1, 1, 42) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 42), 1, 'Як Іринка щодня ходить до школи?', 'Пішки', '["Автобусом","Метром","Велосипедом"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 42), 2, 'Скільки часу займає дорога до школи?', 'Приблизно десять хвилин', '["Пів години","Одну хвилину","Цілу годину"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 42), 3, 'Що Іринка бере зранку?', 'Рюкзак', '["Кошик","Валізу","Парасольку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 42), 4, 'Повз що Іринка проходить спочатку?', 'Повз невеликий парк', '["Повз річку","Повз музей","Повз готель"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 42), 5, 'Хто стоїть біля воріт школи?', 'Кілька однокласників', '["Продавці","Лікарі","Туристи"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 43, 'Мій день народження', '["Сьогодні мій день народження, і мені виповнюється десять років. Мене звати Данило, і цього ранку я став на рік старшим. Зранку мама будить мене усмішкою. На кухні вже пахне тортом. Мама пече його сама і ставить зверху маленькі свічки. Я рахую їх і радію.","Після обіду до мене приходять друзі. Вони приносять прості подарунки і кілька яскравих кульок. Один друг дарує книжку, а інший приносить кольорові олівці. Ми не робимо великої вечірки, але нам весело. Ми граємо в настільну гру, говоримо і сміємося.","Потім мама виносить торт зі свічками. Друзі співають коротке привітання, а я загадую бажання. Ми їмо по невеликому шматку торта. Я дякую всім за подарунки і добрі слова. Увечері кульки ще висять біля вікна, і я довго не хочу лягати спати."]', 1, 1, 43) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 43), 1, 'Як звати хлопця, у якого день народження?', 'Данило', '["Петрик","Сашко","Назар"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 43), 2, 'Скільки років виповнюється Данилу?', 'Десять років', '["Сім років","Дванадцять років","П''ятнадцять років"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 43), 3, 'Чим пахне на кухні зранку?', 'Тортом', '["Кавою","Борщем","Свіжим хлібом"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 43), 4, 'Що дарують друзі Данилу?', 'Книжку і кольорові олівці', '["Квіти і вазу","Рюкзак і рушник","Паску і крашанки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 43), 5, 'Що Данило загадує перед тортом?', 'Бажання', '["Задачу","Пісню","Маршрут"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 44, 'Ранок у сім''ї', '["У нашій сім''ї ранок починається рівно о сьомій годині. Дзвонить будильник, і всі повільно прокидаються. Мене звати Марійка, і я встаю першою. Я застеляю ліжко, брат шукає шкарпетки, а тато вже йде на кухню. У коридорі вже чути швидкі кроки.","Тато готує каву для себе і для мами. На кухні тепло, і вікно вже запітніло від пари. Мама варить кашу для всієї сім''ї. Вона ставить на стіл миски, ложки і жовті яблука. Я наливаю воду в склянки.","О восьмій годині всі вже готові виходити з дому. Тато бере сумку, мама перевіряє ключі, а ми з братом беремо рюкзаки. Перед самими дверима ми швидко бажаємо одне одному гарного дня. Двері зачиняються, і в домі стає зовсім тихо. До вечора наша квартира чекатиме порожня."]', 1, 1, 44) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 44), 1, 'О котрій годині починається ранок у сім''ї Марійки?', 'О сьомій годині', '["О восьмій годині","Опівночі","О третій годині"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 44), 2, 'Що робить Марійка зранку?', 'Застеляє ліжко', '["Готує каву","Шукає шкарпетки","Пече торт"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 44), 3, 'Що готує тато?', 'Каву', '["Кашу","Борщ","Піцу"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 44), 4, 'Що мама варить для всієї сім''ї?', 'Кашу', '["Суп","Вареники","Гречку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 44), 5, 'Що сім''я бажає одне одному перед дверима?', 'Гарного дня', '["Смачної вечері","Доброї ночі","Щасливого Різдва"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 45, 'Річка Дніпро', '["Дніпро — найбільша річка України. Він протікає через багато великих міст і малих сіл. Біля води люди гуляють, відпочивають і довго дивляться на течію. У Києві Дніпро широкий, тому з мостів добре видно його береги. Вранці вода може бути спокійною, а ввечері на ній блищить світло. На березі часто сидять цілі родини з термосами і бутербродами. Для багатьох ця річка є частиною щоденного життя.","Улітку біля Дніпра завжди багатолюдно. Діти і дорослі купаються там, де це безпечно. Хтось сидить на березі з вудкою і терпляче ловить рибу. Інші просто приходять подихати свіжим повітрям або посидіти на теплій траві. Поруч можна побачити рибальські човни і чайок. Дніпро важливий для країни, бо він дає воду, красу і місце для відпочинку. Багато людей люблять цю річку."]', 1, 1, 45) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 45), 1, 'Яка річка є найбільшою в Україні?', 'Дніпро', '["Дунай","Прут","Десна"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 45), 2, 'Через що протікає Дніпро?', 'Через багато міст і сіл', '["Тільки через ліси","Тільки через гори","Тільки через одне місто"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 45), 3, 'Де в Києві добре видно береги Дніпра?', 'З мостів', '["З підвалів","З магазинів","З класів"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 45), 4, 'Що деякі люди роблять на березі з вудками?', 'Ловлять рибу', '["Малюють писанки","Печуть паску","Співають колядки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 45), 5, 'Чому Дніпро важливий для країни?', 'Дає воду, красу і місце для відпочинку', '["Дає квитки і гроші","Дає домашні завдання","Дає теплі куртки"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 46, 'День Незалежності України', '["Мене звати Микола. До 2022 року День Незалежності України був для нашої родини дуже гучним святом. Двадцять четвертого серпня ми з батьками йшли в центр міста. Там проходив парад, грала музика, люди несли прапори і вітали одне одного. Після параду ми слухали концерт на площі і купували морозиво. Увечері родина дивилася феєрверки, і небо було яскравим.","Після російського повномасштабного вторгнення свято змінилося. У місті вже немає такого шуму і великих феєрверків. Батьки кажуть, що тепер головне — безпека і повага до людей, які переживають важкі часи. Ми можемо дивитися короткий концерт онлайн або слухати українські пісні вдома. Іноді сусіди тихо вітають одне одного у дворі і бажають спокійного дня. На балконі тато все одно вішає синьо-жовтий прапор. Я допомагаю йому тримати стрічку, щоб він висів рівно.","Тепер День Незалежності став тихішим, але не менш важливим. Ми накриваємо простий стіл, говоримо про Україну і згадуємо, що свобода дуже важлива. Мама каже, що любити країну можна і в звичайний день. Я дивлюся на прапор і думаю про майбутнє. У цей день я особливо слухаю слова батьків. Потім ми телефонуємо бабусі і разом вітаємо її зі святом. Прапор на балконі видно з вулиці до самого вечора."]', 1, 1, 46) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 46), 1, 'Коли святкують День Незалежності України?', 'Двадцять четвертого серпня', '["Першого вересня","Двадцять восьмого червня","Двадцять п''ятого грудня"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 46), 2, 'Куди родина Миколи ходила до 2022 року?', 'У центр міста', '["До маленького кафе","На ферму","До лікаря"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 46), 3, 'Що тато вішає на балконі?', 'Синьо-жовтий прапор', '["Вишитий рушник","Сімейне фото","Кольорові кульки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 46), 4, 'Що родина робить тепер у цей день?', 'Накриває простий стіл і говорить про Україну', '["Запускає багато феєрверків","Їде до моря","Прибирає клас"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 46), 5, 'Кому родина телефонує зі святом?', 'Бабусі', '["Учительці","Продавчині","Сусідці"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 47, 'Відпочинок в Одесі та на Чорному морі', '["Мене звати Назар Петренко. Улітку наша сім''я їде до Одеси на два тижні. Ми довго чекаємо цієї поїздки, бо всі любимо море. Наш готель недалеко від пляжу, тому зранку ми швидко беремо рушники і йдемо до води. Іти туди лише кілька хвилин.","Ми з сестрою багато плаваємо в Чорному морі. Вода тепла, а хвилі іноді легенько штовхають нас до берега. Після купання ми їмо морозиво і сидимо під парасолькою. Потім збираємо мушлі, але беремо тільки кілька найкрасивіших. Мама просить нас не відходити далеко.","Тато каже, що Чорне море найкраще, бо біля нього легко відпочивати. Мама усміхається і робить фото нашої сім''ї. Увечері ми гуляємо біля готелю і слухаємо шум води. Я згадую цей звук навіть перед сном і довго дивлюся у вікно. Мені подобається Одеса, і я дуже хочу приїхати сюди знову."]', 1, 1, 47) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 47), 1, 'Куди сім''я Назара їде влітку?', 'До Одеси', '["До Львова","До Києва","До Полтави"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 47), 2, 'На скільки часу сім''я їде до Одеси?', 'На два тижні', '["На три дні","На один місяць","На одну годину"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 47), 3, 'Де знаходиться готель?', 'Недалеко від пляжу', '["Біля школи","У горах","На фермі"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 47), 4, 'Що діти збирають після купання?', 'Мушлі', '["Ягоди","Листівки","Колоски"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 47), 5, 'Що мама робить біля моря?', 'Робить фото сім''ї', '["Пише лист","Варить кашу","Плете вінок"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 48, 'День захисників і захисниць', '["Першого жовтня в Україні вшановують захисників і захисниць. Мене звати Вікторія, і для мене це дуже особливий день. У школі вчителька говорить про людей, які бережуть країну. Я слухаю дуже уважно, бо мій тато служить в армії. Він далеко від дому, і я часто думаю про нього.","Після уроків я сідаю за стіл і роблю листівку. На ній малюю синє небо, жовте поле і маленьке серце. Усередині пишу: «Тату, ми тебе чекаємо». Я стараюся писати рівно, бо хочу, щоб тато легко прочитав мої слова. Молодший брат малює поруч маленький синій прапор.","Мама допомагає з конвертом. Вона каже, що такі слова підтримують тата краще за все. Увечері я дивлюся на татове фото і трохи сумую. Конверт лежить на столі і чекає на завтрашню пошту."]', 1, 1, 48) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 48), 1, 'Коли в Україні вшановують захисників і захисниць?', 'Першого жовтня', '["Двадцятого лютого","Першого січня","У третій четвер травня"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 48), 2, 'Чому Вікторія слухає вчительку дуже уважно?', 'Бо її тато служить в армії', '["Бо вона любить математику","Бо завтра іспит","Бо вона хоче купити квіти"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 48), 3, 'Що Вікторія робить після уроків?', 'Листівку', '["Писанку","Сніговика","Салат"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 48), 4, 'Що вона пише всередині листівки?', 'Тату, ми тебе чекаємо', '["Мамо, я тебе люблю","З Новим роком","Я йду до школи"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 48), 5, 'Що малює молодший брат?', 'Маленький прапор', '["Велику річку","Стару школу","Червону калину"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 49, 'День Гідності та Свободи', '["Учителька вимикає світло і вмикає коротке відео про Майдан. Сьогодні двадцять перше листопада, День Гідності та Свободи. Учні сідають тихо. На екрані вони бачать площу, прапори, людей у теплих куртках і багато світла. У класі ніхто не розмовляє.","Після відео вчителька говорить простими словами. Вона каже, що люди вийшли на Майдан, бо хотіли свободи і поваги. Складних пояснень вона не дає і сперечатися не просить. Потім вона питає, що означає це слово в їхньому власному житті. Учні думають і відповідають по черзі.","Один хлопчик каже, що свобода — це можливість говорити правду. Дівчинка додає, що за неї треба вміти відповідати. Учителька усміхається і пише ці слова на дошці. Потім клас кілька хвилин мовчить і про щось думає. Наприкінці уроку діти розуміють це слово краще, ніж на початку."]', 1, 1, 49) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 49), 1, 'Коли проходить урок про День Гідності та Свободи?', 'Двадцять першого листопада', '["Двадцять восьмого червня","Двадцять четвертого серпня","Двадцять п''ятого грудня"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 49), 2, 'Про що вчителька вмикає коротке відео?', 'Про Майдан', '["Про море","Про ферму","Про кафе"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 49), 3, 'Чому люди вийшли на Майдан?', 'Хотіли свободи і поваги', '["Хотіли купити подарунки","Хотіли їхати автобусом","Хотіли співати колядки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 49), 4, 'Що, за словами хлопчика, означає свобода?', 'Можливість говорити правду', '["Можливість не вчитися","Можливість шуміти","Можливість не допомагати"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 49), 5, 'Що дівчинка додає про свободу?', 'Що за неї треба відповідати', '["Вона потребує морозива","Вона потребує тиші в автобусі","Вона потребує нової книжки"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 50, 'День пам''яті жертв Голодомору', '["У четверту суботу листопада Україна згадує жертв Голодомору. Учителька розповідає про це тихо і просто. Вона пояснює, що в 1932-1933 роках багато людей загинули від штучного голоду. На дошці написані роки і слово пам''ять. Діти слухають уважно, бо розуміють, що це день пам''яті.","Свічки запалюють і ставлять на вікна рівно о сьомій вечора. Маленьке світло видно з вулиці, і в будинках стає тихіше. Одна родина ставить свічку на підвіконня біля хліба і кількох колосків. Далі по вулиці горить ще кілька таких вогників. Батьки кажуть дітям, що так люди показують: ми пам''ятаємо.","Ніхто не говорить голосно. Родина стоїть біля вікна кілька хвилин і дивиться на теплий вогник. Діти не знають усіх важких деталей, але розуміють головне: пам''ять потрібна людям. Бабуся тихо тримає руку онуки. Свічка у вікні стає тихим знаком поваги і пам''яті."]', 1, 1, 50) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 50), 1, 'Коли Україна згадує жертв Голодомору?', 'У четверту суботу листопада', '["У другу неділю травня","Першого жовтня","Двадцять другого січня"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 50), 2, 'Про які роки говорить учителька?', '1932-1933 роки', '["1919 рік","2022 рік","1986 рік"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 50), 3, 'О котрій годині люди запалюють свічки у вікнах?', 'О сьомій годині', '["О восьмій ранку","Опівночі","О третій годині"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 50), 4, 'Біля чого родина ставить свічку?', 'Біля хліба і колосків', '["Біля карти і стрічок","Біля торта і кульок","Біля рюкзака і книжок"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 50), 5, 'Чим стає свічка у вікні?', 'Тихим знаком поваги і пам''яті', '["Новою прикрасою","Сигналом для автобуса","Подарунком для дітей"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 51, 'Традиція Івана Купала', '["Увечері я прийшов з братом до річки, бо було свято Івана Купала. Біля води вже збиралася молодь з нашого села. Хлопці ставили лавки, а дівчата несли польові квіти. Поруч діти сиділи з батьками і чекали пісень. На березі було тепло, світло і дуже спокійно.","Моя подруга Марічка плела вінок з ромашок, м''яти і синіх квітів. Поруч інші дівчата теж вибирали квіти для своїх вінків. Потім вони тихо клали вінки на воду. Кожна дівчина мала своє бажання. Люди казали, що вінок, який пливе далеко, приносить щастя в коханні.","Я стояв на березі і дивився на річку. Вода повільно несла квіти, а небо ставало рожевим. Ми слухали пісні, сміялися і пили чай з термоса. Я довго пам''ятав тиху воду. Вінок Марічки поплив далеко і зник за поворотом."]', 1, 1, 51) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 51), 1, 'Куди оповідач прийшов із братом увечері?', 'До річки', '["До школи","До кафе","До магазину"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 51), 2, 'Яке свято було цього дня?', 'Івана Купала', '["День знань","День матері","Новий рік"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 51), 3, 'З чого Марічка плела вінок?', 'З ромашок, м''яти і синіх квітів', '["З калини, листя і яблук","З троянд, хліба і солі","З паперу, ниток і фарб"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 51), 4, 'Куди дівчата клали вінки?', 'На воду', '["На стіл","У рюкзак","На дерево"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 51), 5, 'Що сталося з вінком Марічки?', 'Він поплив далеко', '["Він залишився біля берега","Його забрали діти","Він потонув одразу"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 52, 'Переїзд у нове місто', '["Мене звати Оксана, і моя сім''я Коваленко переїхала з Полтави до Львова. У машині лежали коробки, сумки, іграшки і наші книжки. У мене в рюкзаку лежав старий класний альбом. Я сиділа біля вікна та думала про наш двір. Мій молодший брат теж трохи сумував за друзями і школою.","Коли ми приїхали, Львів здавався великим і незнайомим. Я бачила вузькі вулиці, старі будинки і високі двері. Тато казав, що тут особлива архітектура. Мама показала нам затишні кав''ярні біля площі. У новій квартирі ще пахло фарбою і деревом.","Першого вечора ми гуляли недалеко від дому. У дворі сусідка привіталася з нами. Я написала подрузі повідомлення і пообіцяла приїхати в гості. Потім побачила маленьку книгарню, парк і дітей біля фонтану. Мені стало спокійніше. Я зрозуміла, що новий початок може бути добрим. Львів повільно став мені подобатися."]', 1, 1, 52) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 52), 1, 'Звідки переїхала сім''я Коваленко?', 'З Полтави', '["З Одеси","З Києва","З Черкас"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 52), 2, 'Куди переїхала сім''я?', 'До Львова', '["До Варшави","До села","До Карпат"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 52), 3, 'Що лежало в рюкзаку Оленки?', 'Старий класний альбом', '["Паска і яйця","Квіти і свічки","Мед і варення"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 52), 4, 'Яким здавався Львів спочатку?', 'Великим і незнайомим', '["Маленьким і нудним","Теплим і морським","Порожнім і темним"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 52), 5, 'Що Оленка побачила недалеко від дому?', 'Книгарню, парк і дітей біля фонтану', '["Ринок, автобус і лікарню","Ферму, ліс і корів","Пляж, мушлі і готель"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 53, 'Як готують пампушки', '["У суботу я прокинувся рано, бо в кухні вже пахло тістом. Бабуся Галина готувала пампушки до борщу. Вона усміхнулася і сказала, що поспішати тут не можна. Вона дозволила мені подати чистий білий рушник. Я сів за стіл, узяв чашку гарячого чаю і почав уважно дивитися.","Бабуся замішувала дріжджове тісто. Я ще не вмію так, але бачив, яке воно м''яке. Потім вона робила маленькі круглі кульки і рівно ставила їх на деко. Уранці теплий запах наповнив увесь дім і коридор.","Коли пампушки були готові, бабуся змастила їх часниковим маслом. Я допоміг поставити тарілки на стіл і покликав тата з двору. На плиті вже стояв борщ. Мені дуже хотілося скуштувати їх одразу. До обіду треба було почекати ще зовсім трохи. Перша пампушка обпекла мені пальці."]', 1, 1, 53) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 53), 1, 'Хто готував пампушки до борщу?', 'Бабуся Галина', '["Мама","Тато","Сусідка"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 53), 2, 'Коли оповідач прокинувся?', 'У суботу рано', '["У неділю ввечері","У понеділок після школи","Опівночі"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 53), 3, 'З якого тіста бабуся робила пампушки?', 'З дріжджового тіста', '["З пісочного тіста","З сирного тіста","З тіста для піци"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 53), 4, 'Чим бабуся змастила готові пампушки?', 'Часниковим маслом', '["Медом","Варенням","Сметаною"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 53), 5, 'Що вже стояло на плиті?', 'Борщ', '["Каша","Узвар","Кава"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 54, 'Прогулянка Львовом', '["Туристи приїхали до Львова вранці і відразу пішли на площу Ринок. Вони хотіли побачити центр міста без поспіху. На площі стояли старі будинки з гарними вікнами. Туристи робили фото, дивилися вгору і слухали коротку розповідь гіда. Одна жінка фотографувала синій балкон над кафе.","Потім вони зайшли на вузьку вулицю біля площі. Там були маленькі крамниці, книгарні і кав''ярні. У вікнах лежали листівки, чашки, шоколад і сувеніри. Біля одного будинку грали вуличні музиканти. Діти слухали їх біля дверей. Їхня музика звучала легко, і люди зупинялися на кілька хвилин.","Львів здавався туристам середньовічною казкою. Тут кожна вулиця була іншою, але гуляти містом було легко. Настрій був святковий і спокійний. Увечері вони купили листівки для друзів і ще раз подивилися на площу. Туристи сказали, що хочуть повернутися до Львова знову."]', 1, 1, 54) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 54), 1, 'Куди туристи пішли у Львові спочатку?', 'На площу Ринок', '["До моря","На ферму","До школи"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 54), 2, 'Що туристи слухали на площі?', 'Коротку розповідь гіда', '["Урок музики","Новини","Телефонну розмову"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 54), 3, 'Що фотографувала одна жінка?', 'Синій балкон над кафе', '["Червону калину","Автобусну зупинку","Стару вишиванку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 54), 4, 'Хто грав біля одного будинку?', 'Вуличні музиканти', '["Учні","Продавці","Лікарі"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 54), 5, 'Що туристи купили ввечері?', 'Листівки для друзів', '["Мед і варення","Квіти для вчителів","Мушлі"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 55, 'Перший заробіток', '["Минулого літа я вперше заробив свої гроші. Мене звати Данило, і мені тоді було дванадцять років. Наша сусідка тітка Лариса попросила мене допомогти в саду. Я приходив до неї після сніданку і працював одну годину. Робота була проста, але потрібна, тому я не запізнювався.","Я поливав грядки, збирав сухе листя і носив воду до молодих дерев. Іноді було жарко, тому я робив коротку перерву в тіні. Сусідка дякувала мені і казала, що сад виглядає краще. Вона навіть показала мені свої нові квіти. Наприкінці тижня вона дала мені гроші.","Я купив собі цікаву книжку і морозиво біля магазину. Решту поклав у коробку. Тоді я зрозумів, що гроші приходять через працю і час. Коробка стоїть там і досі, і я нічого з неї не брав."]', 1, 1, 55) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 55), 1, 'Як звати хлопця, який уперше заробив гроші?', 'Данило', '["Артем","Олег","Сашко"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 55), 2, 'Хто попросив Данила допомогти в саду?', 'Тітка Лариса', '["Бабуся Галина","Учителька","Мама"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 55), 3, 'Скільки часу Данило працював щодня?', 'Одну годину', '["Десять хвилин","Три години","Цілий день"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 55), 4, 'Що Данило робив у саду?', 'Поливав грядки і носив воду', '["Писав листи","Готував борщ","Малював писанки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 55), 5, 'Що Данило купив за частину грошей?', 'Книжку і морозиво', '["Рюкзак і рушник","Піцу і сік","Квіти і вазу"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 56, 'Великдень: традиції і значення', '["Великдень є важливим святом в Україні, але його дата щороку інша. Щоб знайти точний день, люди дивляться церковний календар. Зазвичай це неділя після весняного повного місяця. Це правило не завжди легко порахувати самому. Так родина знає, коли пекти паску, фарбувати яйця і готувати кошик.","Сім''ї святкують Великдень по-різному. Одні йдуть до церкви вночі, коли ще темно і тихо. Інші приходять уранці з дітьми, бо так зручніше. Біля храму люди вітаються спокійно і радісно. У багатьох людей є великодній кошик. У ньому лежить паска, яйця, сир, ковбаса і маленька свічка.","Наприклад, одна сім''я з Києва пече паску вдома, а сусіди купують її в пекарні. Хтось фарбує яйця в суботу, а хтось робить це раніше. Після служби люди вітають одне одного і сідають за стіл. У домі стає світло і святково. Молодші слухають старших, але додають свої звички. Так старі й нові традиції живуть разом."]', 1, 1, 56) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 56), 1, 'Чому родина дивиться церковний календар?', 'Щоб знайти дату Великодня', '["Щоб купити квиток","Щоб вибрати школу","Щоб знайти автобус"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 56), 2, 'Що родина знає завдяки даті Великодня?', 'Коли пекти паску і фарбувати яйця', '["Коли їхати до моря","Коли починати іспит","Коли відкривати магазин"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 56), 3, 'Що лежить у великодньому кошику?', 'Паска, яйця, сир, ковбаса і свічка', '["Піца, сік і шоколад","Книжки, ручки і зошити","Мед, варення і коробки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 56), 4, 'Де одна сім''я з Києва пече паску?', 'Вдома', '["У школі","На ринку","У музеї"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 56), 5, 'Що живе разом у великодніх традиціях?', 'Старі й нові традиції', '["Шум і суперечки","Місто і автобус","Риба і фрукти"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 57, 'Українська вишивка', '["Українська вишивка живе в багатьох родинах. Бабусі передають сорочки, рушники і знання своїм дітям та онукам. Дівчина може отримати вишиту сорочку від мами. Хлопець може берегти рушник, який зробила його бабуся. Так пам''ять родини переходить від покоління до покоління.","У різних регіонах є свої орнаменти і кольори. Десь люди люблять червоний і чорний, а десь синій, зелений або білий. На сорочках можна побачити квіти, листя і прості геометричні знаки. Кожен узор щось означає. Найчастіше він пов''язаний з домом і родиною.","Вишиванка є не тільки красивим одягом. Для багатьох людей це знак того, хто вони і звідки. Це також пам''ять і гордість. Її носять на свята, у школі або на важливі зустрічі. Коли люди вдягають вишиту сорочку, вони часто згадують свою сім''ю. Тому вишивку носять бережно і з повагою."]', 1, 1, 57) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 57), 1, 'Що бабусі передають дітям та онукам?', 'Сорочки, рушники і знання', '["Квитки, гроші і чеки","Мушлі, яблука і воду","Каву, сік і печиво"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 57), 2, 'Що може отримати дівчина від мами?', 'Вишиту сорочку', '["Новий телефон","Автобусний квиток","Кошик із паскою"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 57), 3, 'Які узори можна побачити на сорочках?', 'Квіти, листя і геометричні знаки', '["Моря, гори і автобуси","Піцу, сир і соус","Годинники, чашки і книжки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 57), 4, 'З чим часто пов''язані узори?', 'З домом і родиною', '["З магазином і касою","З лікарем і ліками","З іспитом і тестами"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 57), 5, 'Як люди носять вишивку?', 'Бережно і з повагою', '["Швидко і сердито","Гучно і весело","Таємно і сумно"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 58, 'Мандрівка Карпатами', '["Мене звати Христина, і моя сім''я Шевченко провела тиждень у Карпатах. Ми жили в маленькому будинку біля лісу. Навколо росли ягоди і високі трави. Щоранку я відкривала вікно і бачила зелені гори. Повітря було свіже, тому всі швидко прокидалися і хотіли йти надвір.","Удень ми ходили простими стежками в горах. Тато показував нам дерева, а мама фотографувала краєвиди. Ми не поспішали і часто відпочивали біля великих каменів. Ми дихали свіжим повітрям і багато мовчали. У рюкзаку були бутерброди, вода і яблука. Після обіду ми з братом довго плавали в чистій холодній річці біля села.","Увечері ми сиділи на лавці й пили теплий чай. Мій брат сказав, що це найкращі канікули. Інші діти теж погодилися з ним. Мама усміхалася. Я думала так само. Удома в рюкзаку ще довго пахло димом і хвоєю."]', 1, 1, 58) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 58), 1, 'Де сім''я Шевченко провела тиждень?', 'У Карпатах', '["В Одесі","У Варшаві","У Полтаві"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 58), 2, 'Де жила сім''я?', 'У маленькому будинку біля лісу', '["У готелі біля пляжу","У квартирі в центрі","У школі"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 58), 3, 'Що Марійка бачила щоранку з вікна?', 'Зелені гори', '["Синє море","Міський ринок","Шкільний двір"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 58), 4, 'Що було в рюкзаку?', 'Бутерброди, вода і яблука', '["Книжки, ручки і зошити","Квіти, свічки і стрічки","Кава, сік і печиво"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 58), 5, 'Де Марійка з братом плавали після обіду?', 'У чистій річці біля села', '["У морі біля Одеси","У басейні","У ставку біля школи"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 59, 'Як я навчився готувати', '["Улітку мама почала вчити мене готувати прості страви. Мене звати Артем, і раніше я не підходив до плити. Спочатку я тільки мив овочі і подавав тарілки. Потім мама сказала, що я вже можу зробити щось сам. Я записував поради у маленький зошит. Мені було цікаво і трохи страшно.","Першою стравою були варені яйця. Я дивився на годинник і слухав мамині поради. Після цього я навчився варити гречку в маленькій каструлі. Вона не завжди була ідеальна, але сім''я їла її з усмішкою і хвалила мене.","Пізніше ми разом смажили котлети. Мама стояла поруч і показувала, коли їх треба перевернути. Тепер я можу приготувати простий обід для всієї родини: гречку, салат і котлети. Це вже схоже на справжню допомогу вдома. Я ще питаю поради і прибираю після себе, але вже почуваюся більш самостійним."]', 1, 1, 59) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 59), 1, 'Хто почав учити Артема готувати?', 'Мама', '["Бабуся","Тато","Учителька"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 59), 2, 'Що Артем робив спочатку?', 'Мив овочі і подавав тарілки', '["Смажив котлети сам","Писав листи","Продавав мед"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 59), 3, 'Куди Артем записував поради?', 'У маленький зошит', '["На дошку","У телефон мами","На конверт"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 59), 4, 'Якою була перша страва?', 'Варені яйця', '["Борщ","Пампушки","Піца"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 59), 5, 'Який простий обід Артем може приготувати тепер?', 'Гречку, салат і котлети', '["Паску, яйця і сир","Каву, сік і печиво","Варення, мед і чай"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 60, 'Моя бабуся і її рецепти', '["Мою бабусю звати Параска. Вона знає багато рецептів, але не любить довго про них говорити. Мене вдома кличуть Катрусею. Ми з братом приїжджаємо до неї на вихідних. На кухню ми заходимо найпершими. Бабуся радіє і одразу ставить на плиту чайник.","Найкраще бабуся готує куліш і тонкі млинці. Одне вона ставить у велику миску, друге складає на тарілку. У хаті смачно пахне їжею і свіжим гарячим чаєм. Я люблю дивитися, як вона все це готує. Бабуся додає, що добра страва потребує любові й терпіння.","Ми допомагаємо накривати великий стіл. Я ставлю ложки, а брат приносить свіжий хліб. Після обіду бабуся обов''язково питає, чи все було смачно. Ми киваємо і просимо ще млинців із медом. Вона знову йде до плити, хоча ми вже давно наїлися і сміємося."]', 1, 1, 60) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 60), 1, 'Як звати бабусю Катрусі?', 'Параска', '["Галина","Олена","Лариса"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 60), 2, 'Коли Катруся з братом приїжджають до бабусі?', 'На вихідних', '["Щоранку","Тільки взимку","Після іспиту"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 60), 3, 'Що бабуся готує найкраще?', 'Куліш і млинці', '["Піцу і салат","Холодець і борщ","Сік і шоколад"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 60), 4, 'Що брат приносить до столу?', 'Хліб', '["Квіти","Книжку","Прапор"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 60), 5, 'Що бабуся робить після обіду?', 'Знову йде до плити', '["Лягає відпочивати","Іде в магазин","Вмикає телевізор"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 61, 'Традиційний одяг різних регіонів', '["У старій скрині святкова сорочка лежить зверху. У кожному регіоні України такі сорочки виглядають по-своєму. Колись таку сорочку вдягали на весілля і великі родинні свята. Решту року вона чекала в темряві, складена рівно вчетверо. Колір і візерунок одразу показували, звідки людина родом. А ще вони говорили про смак родини і про працю майстрині.","На Полтавщині вишивають червоними і чорними нитками. Узор виходить рівний, спокійний, майже без зайвих деталей. У гуцульських селах усе інакше. Там люблять яскраві кольори, теплі кептарі, широкі пояси і багато прикрас. Це пасує до гірських доріг, гучної музики і швидких танців. Одяг тримає в собі те, чим живе край.","Сьогодні такі сорочки не носять щодня, але їх дістають на свята і вистави. У музеї вони стоять за склом, і діти довго порівнюють кольори. Хтось обов''язково впізнає узор свого краю."]', 1, 1, 61) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 61), 1, 'Що показував традиційний одяг?', 'Звідки людина родом', '["Скільки в неї грошей","Куди їде автобус","Який у неї телефон"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 61), 2, 'Які нитки часто використовують на Полтавщині?', 'Червоні і чорні', '["Сині і зелені","Білі і жовті","Рожеві і сірі"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 61), 3, 'Який одяг у Гуцульському краї?', 'Яскравий, з багатьма прикрасами', '["Темний і простий","Такий самий, як усюди","Зовсім без кольорів"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 61), 4, 'Де діти можуть бачити справжні речі?', 'У музеї', '["У кафе","На автобусі","У річці"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 61), 5, 'Де сьогодні можна побачити такий одяг?', 'У музеї, за склом', '["У кожній школі","У магазині біля дому","На вокзалі"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 62, 'Козацька історія', '["Посеред Дніпра лежить довгий зелений острів Хортиця. Саме там колись була головна громада запорізьких козаків. Козаки були сміливими воїнами, а головне — вільними людьми. Вони самі обирали собі отамана і разом вирішували важливі справи. Ніхто не наказував їм, як жити. Слово і честь важили для них більше за багатство.","Козаки захищали свою землю і людей, які жили поруч. Коли приходила біда, вони не стояли осторонь. Життя на Січі було суворе й просте. Вони разом працювали, разом їли і слухали старших. Той, хто хотів бути вільним, мусив уміти жити поруч з іншими людьми. У цьому й була сила громади.","Сьогодні про козаків нагадують пісні, танці й старі легенди. На святах діти танцюють гопак, а в музеях слухають розповіді про Хортицю. Майже в кожній родині знають хоча б одну козацьку пісню. Козаків не забули."]', 1, 1, 62) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 62), 1, 'Де жили запорізькі козаки?', 'Біля Дніпра, на Хортиці', '["Біля Чорного моря","У Варшаві","У горах Карпат"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 62), 2, 'Що для козаків важило більше за багатство?', 'Слово і честь', '["Земля і худоба","Зброя і човни","Пісні і танці"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 62), 3, 'Що було дуже важливим для козаків?', 'Слово і честь', '["Квиток і чек","Сік і шоколад","Фото і телефон"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 62), 4, 'Хто обирав отамана?', 'Самі козаки', '["Старійшини сусідніх сіл","Гетьман з Києва","Ніхто"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 62), 5, 'Де живуть козацькі традиції?', 'У піснях, танцях і легендах', '["У касах і чеках","У зошитах з математики","У рецептах піци"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 63, 'Калина — символ України', '["Повз кущ біля нашої школи я проходив сто разів. Він просто ріс собі коло паркану, і я на нього не дивився. А сьогодні вчителька принесла в клас гілку з червоними ягодами. Вона сказала, що червона калина — символ України. Я впізнав той кущ одразу. Мені стало трохи соромно, що я його не помічав.","Потім ми говорили, де ще можна зустріти калину. Вона є в піснях, у вишивці і в старих віршах. Бабуся справді часто співає про червону калину. Ще вчителька дала нам спробувати ягоду. Ягода виявилася гіркою, і половина класу засміялася. Учителька додала, що калина означає красу, силу і рідну землю.","Після уроків я спеціально пішов додому повз той паркан. Ягоди висіли низько, майже над самою землею. Я зірвав одну. Тепер я дивлюся на цей кущ зовсім інакше."]', 1, 1, 63) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 63), 1, 'Що є символом України в історії?', 'Червона калина', '["Соняшник","Писанка","Дніпро"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 63), 2, 'Де оповідач бачив кущ калини раніше?', 'Біля школи', '["Біля моря","На ринку","У кафе"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 63), 3, 'Що вчителька принесла в клас?', 'Гілку з червоними ягодами', '["Стару книжку","Кошик яблук","Карту України"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 63), 4, 'Які на смак ягоди калини?', 'Гіркі', '["Солодкі","Солоні","Кислі як лимон"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 63), 5, 'Що може означати калина?', 'Красу, силу і рідну землю', '["Шум, поспіх і дорогу","Гроші, чек і решту","Каву, торт і печиво"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 64, 'Нові друзі на мовних курсах', '["Курси польської мови починалися о шостій вечора. На першому занятті кожен писав своє ім''я на папірці. Я написала «Ірина» і поклала його перед собою. Спочатку я трохи хвилювалася, бо не знала в групі нікого. Поруч сиділи люди з різних міст України. Були й студенти з інших країн.","На уроці ми вчили прості слова і короткі діалоги. Викладач говорив повільно. Ліворуч від мене сиділа дівчина з Харкова, а навпроти — хлопець із Грузії. Ми всі однаково плуталися в довгих словах. Після заняття хтось запропонував посидіти разом. Маленьку кав''ярню знайшли просто за рогом.","Там ми пили каву і говорили польською, скільки могли. Коли слів бракувало, переходили на українську. Мої помилки виправляли одразу, і ніхто з цього не сміявся. Тепер я приходжу раніше, щоб устигнути поговорити з ними до уроку."]', 1, 1, 64) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 64), 1, 'На які курси записалася Ірина?', 'Польської мови', '["Англійської мови","Музики","Малювання"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 64), 2, 'Чому Ірина спочатку хвилювалася?', 'Бо не знала нікого в групі', '["Бо забула зошит","Бо запізнилася","Бо не любила мови"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 64), 3, 'Що вчили на першому уроці?', 'Прості слова і короткі діалоги', '["Складні пісні","Довгі вірші","Історію Львова"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 64), 4, 'Хто сидів поруч з Іриною?', 'Дівчина з Харкова', '["Хлопець із Грузії","Учителька","Подруга з Польщі"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 64), 5, 'Куди студенти пішли після заняття?', 'До маленької кав''ярні', '["До музею","На ринок","До річки"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 65, 'Київ — місто на горах', '["Від вокзалу я пішов пішки і швидко втомився. У Києві вулиця весь час іде або вгору, або вниз, і ноги це відчувають. Місто стоїть на горах над Дніпром. З верхніх вулиць видно річку, мости і дахи нижнього міста. Навіть у центрі всюди дерева, схили і широке небо над водою. Я зупинявся частіше, ніж фотографував.","Другого дня я пішов на Андріївський узвіз. Це вузька вулиця, де сидять художники і продають сувеніри. На столиках лежали картини, вишиті серветки і чашки. Люди йшли повільно, бо хотіли все роздивитися. Я купив магніт для сестри і листівку для мами. Біля сходів грав музикант, а монети дзвеніли в його шапці.","Нагорі я став біля огорожі і подивився вниз. Будинки здавалися маленькими, а Дніпро блищав далеко внизу. Поруч тихо фотографували туристи. Я простояв там довше, ніж збирався."]', 1, 1, 65) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 65), 1, 'Як оповідач дістався від вокзалу?', 'Пішов пішки', '["Поїхав автобусом","Узяв таксі","Поїхав метро"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 65), 2, 'Що видно з високих вулиць Києва?', 'Дніпро, мости і нижню частину міста', '["Море, пляж і готель","Ферму, сад і хлів","Ринок, касу і чек"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 65), 3, 'Куди оповідач пішов одного дня?', 'На Андріївський узвіз', '["На площу Ринок","До Чорного моря","На ферму"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 65), 4, 'Що оповідач купив для сестри?', 'Маленький магніт', '["Книжку","Писанку","Букет"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 65), 5, 'Що блищало далеко внизу?', 'Дніпро', '["Море","Сніг","Вікно кафе"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 66, 'Останній дзвоник', '["Наприкінці травня у школі завжди пахне квітами. Останній дзвоник у нас, як і в усіх школах, був у п''ятницю. Зранку мама застібала мені блузку і казала: «Машо, не крутися». У дворі стояли учні, батьки і вчителі. Біля входу всі фотографувалися.","Найголовніший день був не в нас, а у випускників. Вони стояли попереду з квітами і раптом здавалися набагато старшими, ніж завжди. Кілька дівчат плакали, бо прощалися з класом. Хлопці сміялися і жартували голосніше, ніж треба. Але від класу не відходили.","Учителі бажали всім удачі, легких іспитів і довгого літа. Директор говорив недовго. Потім пролунав дзвоник, і на секунду двір став зовсім тихим. Далі всі плескали, а малюки дивилися знизу вгору.","Я стояла біля своєї подруги і думала про наш клас. Я знаю, що сумуватиму за цими днями. А в понеділок я вже їду до моря."]', 1, 1, 66) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 66), 1, 'Коли в школі Маші був останній дзвоник?', 'Наприкінці травня', '["Першого вересня","Двадцятого лютого","У третій четвер травня"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 66), 2, 'Що Маша вдягнула зранку?', 'Блузку', '["Вишиванку з синім орнаментом","Теплу куртку і шарф","Спортивну форму"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 66), 3, 'Для кого цей день був особливим?', 'Для випускників', '["Для продавців","Для туристів","Для лікарів"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 66), 4, 'Що бажали учителі?', 'Удачі, легких іспитів і довгого літа', '["Смачної вечері","Тихої дороги","Нової роботи"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 66), 5, 'Що Маша робитиме в понеділок?', 'Поїде до моря', '["Піде на іспит","Залишиться вдома","Поїде до бабусі"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 67, 'Новий рік: традиції та родина', '["У дитинстві Новий рік починався для мене з запаху мандаринів і хвої. До 2022 року в місті святкували гучно і довго. Люди виходили на площу, купували солодощі і чекали півночі разом. Опівночі феєрверки освітлювали все небо над дахами і над річкою. У дворах діти сміялися, а дорослі вітали сусідів до самого ранку. Удома нас завжди чекав накритий стіл. На ньому були олів''є, запечена картопля, мандарини, сирники і мамин пиріг.","Тепер свято стало тихішим. Після початку повномасштабної війни люди більше думають про безпеку і близьких. Стіл ми накриваємо так само, тільки без гучної музики і без гостей. Уся сім''я збирається разом, як і раніше. Тато перевіряє новини, а мама раз у раз виглядає у вікно. Дідусь згадує минулий рік, а я думаю, чого хочу навчитися далі. Ми телефонуємо родичам, які тепер живуть в інших країнах.","Опівночі ми вітаємо одне одного і бажаємо миру, здоров''я і сил. За вікном іноді видно далекі феєрверки, але їх набагато менше, ніж колись. Ми дивимося коротко і повертаємося до теплого столу. Потім пишемо на папірцях маленькі бажання і кладемо їх біля ялинки. Молодші діти вже сплять на дивані. Хочеться, щоб наступний рік був спокійнішим."]', 1, 1, 67) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 67), 1, 'Із чого починався Новий рік у дитинстві?', 'Із запаху мандаринів і хвої', '["Із першого снігу","Із подарунків під ялинкою","Із дзвінка від бабусі"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 67), 2, 'Які страви були на столі раніше?', 'Олів''є, картопля, мандарини, сирники і пиріг', '["Паска, яйця і сир","Борщ, пампушки і часник","Кава, сік і печиво"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 67), 3, 'Чому тепер свято стало тихішим?', 'Люди більше думають про безпеку і близьких', '["Усі забули про свято","Немає мандаринів","Школа зачинена"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 67), 4, 'Кому родина телефонує?', 'Родичам в інших країнах', '["Продавцям на ринку","Учням у класі","Туристам у Львові"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 67), 5, 'Що родина кладе біля ялинки?', 'Маленькі бажання на папері', '["Квитки на автобус","Банки з варенням","Старі книжки"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 68, 'Малий бізнес у селі', '["Тетяна живе в невеликому селі, де всі одне одного знають. Її родина тримає пасіку і великий сад. Банок щороку залишалося більше, ніж з''їдала сім''я. Одного дня вона вирішила продавати домашній мед і варення онлайн. Спочатку здавалося, що це просто. Насправді треба було знайти коробки, навчитися фотографувати і писати описи.","Найважче було з покупцями, які не розуміли онлайн-замовлень. Вони дзвонили по кілька разів і питали одне й те саме. Тетяна не сердилася. Вона пояснювала все спокійно, записувала адреси і перевіряла кожну посилку. Іноді син показував їй, як зробити фото телефоном. Перші місяці вона працювала значно більше, ніж заробляла, і майже не спала.","Через пів року в неї з''явилися постійні клієнти. Одні замовляли мед до чаю, а інші варення для дітей. Дехто радив її сторінку друзям. Тепер вона підписує коробки своїм ім''ям."]', 1, 1, 68) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 68), 1, 'Де живе Тетяна?', 'У невеликому селі', '["У великому місті","Біля моря","У Варшаві"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 68), 2, 'Що тримає родина Тетяни?', 'Пасіку і сад', '["Ферму з коровами","Кафе","Книжковий магазин"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 68), 3, 'Що Тетяна вирішила продавати онлайн?', 'Домашній мед і варення', '["Піцу і сік","Книжки і зошити","Квіти і листівки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 68), 4, 'Кого Тетяна іноді просила допомогти з телефоном?', 'Сина', '["Бабусю","Учительку","Сусідку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 68), 5, 'Коли в Тетяни з''явилися постійні клієнти?', 'Через пів року', '["Через один день","Через тиждень","Через три роки"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 69, 'День захисників: листи із фронту', '["У День захисників наш клас не мав звичайних уроків. Учителька принесла чистий папір, конверти і кольорові олівці. Ми писали листи солдатам. Вона сказала, що такі листи важать більше, ніж здається. У класі стало дуже тихо. Я довго не знала, з чого почати. Учителька нахилилася до мене: «Оленко, пиши, як думаєш».","Я намалювала синьо-жовтий прапор у верхньому куті аркуша. Під ним написала: «Дякуємо за захист». Поруч додала сонце і кілька ромашок. Мені хотілося, щоб лист був схожий не на новини, а на лист із дому. Моя подруга написала коротке побажання здоров''я. Хтось намалював дім, садок і кота на паркані.","Після уроку ми поклали листи в конверти. Учителька сказала, що їх передадуть разом з іншою допомогою. Я трохи хвилювалася: мій лист поїде до когось незнайомого. Нехай він знає, що про нього тут пам''ятають."]', 1, 1, 69) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 69), 1, 'Що клас Оленки писав у День захисників?', 'Листи солдатам', '["Контрольну роботу","Рецепти","Оголошення"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 69), 2, 'Що принесла учителька?', 'Папір, конверти і кольорові олівці', '["Квіти, свічки і стрічки","Мед, варення і коробки","Каву, сік і печиво"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 69), 3, 'Що Оленка намалювала у верхньому куті листа?', 'Синьо-жовтий прапор', '["Червону калину","Соняшникове поле","Карту Львова"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 69), 4, 'Які слова написала Оленка?', 'Дякуємо за захист', '["Мамо, я тебе люблю","Христос Воскрес","Я хочу подорожувати"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 69), 5, 'Що зробили з листами після уроку?', 'Поклали в конверти', '["Повісили на стіні","Віддали батькам","Залишили в класі"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 70, 'Поїздка до бабусі в село', '["Автобус до Черкаської області їде майже чотири години. Щоліта я проводжу їх біля вікна. За склом тягнуться поля, лісосмуги і маленькі зупинки без назв. Останні кілометри я вже впізнаю кожен поворот. Бабуся стоїть біля хвіртки ще до того, як автобус зупиниться. У селі мене ніхто не називає Олександром — тільки Сашком.","Торгових центрів у селі немає. Зате біля хати росте великий сад, а за городом починається стежка до лісу. Уранці повітря таке чисте, що від нього трохи паморочиться голова. Я ношу бабусі воду, збираю яблука і бігаю на річку. Увечері ми сидимо під старою грушею і слухаємо, як гуде село.","За кілька днів я перестаю поспішати. Сплю до дев''ятої, їм двічі більше, ніж удома. Наприкінці серпня бабуся кладе мені в рюкзак яблука і мед. Я вже рахую, скільки залишилося до наступного літа."]', 1, 1, 70) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 70), 1, 'Куди Сашко їде щоліта?', 'До бабусі в село', '["До моря","До Львова","До Варшави"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 70), 2, 'У якій області живе бабуся?', 'У Черкаській області', '["У Львівській області","В Одеській області","У Полтавській області"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 70), 3, 'На чому Сашко їде до бабусі?', 'На автобусі', '["На потязі","На велосипеді","На човні"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 70), 4, 'Що Сашко допомагає робити в селі?', 'Носити воду і збирати яблука', '["Писати листи","Продавати мед","Смажити котлети"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 70), 5, 'Де Сашко і бабуся сидять увечері?', 'Під старою грушею', '["Біля шкільної дошки","У кафе біля вікна","На морському пляжі"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 71, 'Соняшники — символ степу', '["Улітку дорога на південь кілометрами йде між жовтими полями. Соняшники стоять рівними рядами і всі повертають голови в один бік. Такі поля впізнають одразу, навіть на фото з чужої країни. Україна вирощує більше соняшнику, ніж майже будь-яка країна світу. Тому ці квіти видно біля доріг, сіл і залізниць по всій країні. Водії іноді зупиняються, щоб просто постояти на узбіччі. Здалеку таке поле схоже на велике тепле море.","Для багатьох людей соняшник означає дім, тепло і рідну землю. Його малюють на листівках, вишивають на серветках, ставлять у вазу на столі. Восени з насіння роблять олію, і густий запах стоїть на все подвір''я. Дитина, яка виросла в селі, впізнає цей запах із заплющеними очима. Наприкінці літа поле темніє. Але доти воно світиться так, що очам стає гаряче."]', 1, 1, 71) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 71), 1, 'Де влітку стоять соняшники?', 'Біля доріг, сіл і залізниць', '["У класах і лікарнях","У кафе і магазинах","На дахах будинків"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 71), 2, 'Якою здається соняшникова нива здалеку?', 'Великим теплим морем', '["Темним лісом","Холодною річкою","Маленьким садом"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 71), 3, 'Що соняшник означає для багатьох людей?', 'Дім, тепло і рідну землю', '["Шум, поспіх і місто","Квиток, чек і гроші","Іспит, план і помилки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 71), 4, 'Де малюють соняшники?', 'На листівках і серветках', '["На квитках і чеках","На підручниках з математики","На автобусних зупинках"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 71), 5, 'Що нагадують соняшники?', 'Дім, тепло і рідну землю', '["Море, готель і мушлі","Каву, шоколад і воду","Зошит, ручку і дошку"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 72, 'Українська мова у світі', '["У суботу вранці в Торонто відчиняється невелика школа. Діти приходять туди не по математику, а щоб співати і читати українською. Такі школи вихідного дня є в Канаді, США і Польщі. Українська — одна з найпоширеніших слов''янських мов у світі. Нею говорять в Україні і в українських громадах за кордоном. Удома родини бережуть її просто тим, що розмовляють нею щодня. Діти вчать там привітання, пісні і короткі вірші напам''ять.","Останніми роками українську почали вивчати й ті, хто раніше про неї не думав. Хтось має друзів з України, хтось хоче читати новини без перекладача. На курсах слухають короткі діалоги, повторюють нові слова і плутають наголоси. Найчастіше питають про вимову. Хтось потім їде в Україну і чує ці слова просто на вулиці. Після цього незнайома людина перестає бути зовсім чужою."]', 1, 1, 72) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 72), 1, 'Де говорять українською мовою?', 'В Україні та громадах за кордоном', '["Тільки в одному місті","Тільки в школах","Тільки в музеях"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 72), 2, 'У яких країнах можна почути українську?', 'У Канаді, США і Польщі', '["В Італії, Іспанії і Греції","У Японії, Китаї і Кореї","У Норвегії, Швеції і Данії"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 72), 3, 'Де родини часто бережуть українську мову?', 'Вдома і в школах вихідного дня', '["У касі магазину","На футбольному полі","У лікарні"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 72), 4, 'Чому деякі люди вивчають українську?', 'Хочуть читати новини без перекладача', '["Хочуть купити автобус","Хочуть навчитися плавати","Хочуть зробити сніговика"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 72), 5, 'Що стається після кількох фраз українською?', 'Незнайома людина перестає бути чужою', '["Розмова закінчується","Люди переходять на англійську","Ніхто нічого не розуміє"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 73, 'Перша подорож за кордон', '["У квитку стояло: Марія, шістнадцять років, Київ — Варшава. Це була моя перша поїздка за кордон. Їхали ми з тіткою, і всю дорогу я майже не відривалася від вікна. Раніше інші країни я бачила тільки на фото. Тому я трохи боялася, що все виявиться не таким.","Варшава зустріла широкими вулицями, трамваями і старими будинками в центрі. Польська мова здавалася майже своєю. Я впізнавала окремі слова, а потім губилася в довгих реченнях. Продавчиня в булочній повторила мені все двічі, повільніше. Тітка сміялася, що я розумію кожне третє слово. Це було дивно: близько і водночас не зовсім зрозуміло.","Європа перестала бути для мене картинкою з підручника. Люди там мали свої звички, але багато речей були знайомими. Удома я почала слухати, як говорять іноземці в метро. І вже дивилася, куди можна поїхати наступного літа."]', 1, 1, 73) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 73), 1, 'Як звати дівчину в історії?', 'Марія', '["Оксана","Ірина","Ганна"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 73), 2, 'У якому віці Марія вперше поїхала за кордон?', 'У шістнадцять років', '["У десять років","У двадцять років","У сім років"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 73), 3, 'До якого міста поїхала Марія?', 'До Варшави', '["До Львова","До Одеси","До Києва"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 73), 4, 'З ким Марія поїхала за кордон?', 'З тіткою', '["З мамою","З братом","З класом"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 73), 5, 'Що Марія почала уважніше слухати після подорожі?', 'Як говорять іноземці', '["Народні казки","Поради лікаря","Новини спорту"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 74, 'День вишиванки: традиція і сучасність', '["Того ранку в нашому класі майже не було звичайного одягу. Сорочки, блузки, навіть светри — усе вишите. День вишиванки припадає на третій четвер травня. Я знала про це, але вперше побачила таке ціле подвір''я. Ми фотографувалися групами і поодинці. Учителька сказала, що сьогодні так само вдягаються українці по всьому світу.","Увечері я знайшла в мережі фото з Торонто і Варшави. Там теж стояли люди у вишитих сорочках, тільки з іншим небом за спиною. Виявилося, що свято придумали студенти. Спочатку їх було кілька десятків в одному університеті. Ніхто не давав наказу, і саме тому воно розійшлося так швидко. Тепер вишиванку вдягають на роботу, на пари і на зустрічі з друзями.","Мене найбільше здивували дизайнери, які поєднують вишивку із сучасним одягом. Узор може бути на жакеті, на сукні або на рукаві футболки. Це вже не музейна річ. Наступного травня я вдягну свою."]', 1, 1, 74) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 74), 1, 'Коли святкують День вишиванки?', 'У третій четвер травня', '["У другу неділю травня","Двадцять четвертого серпня","Дев''ятнадцятого січня"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 74), 2, 'Де оповідачка вперше побачила це свято?', 'У своєму класі', '["У музеї","На ринку","У кафе"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 74), 3, 'Як почався День вишиванки?', 'Його придумали студенти', '["Як шкільний іспит","Як родинний рецепт","Як спортивне змагання"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 74), 4, 'Куди тепер вдягають вишиванку?', 'На роботу, на пари і на зустрічі', '["Тільки в музей","Тільки на пляж","Тільки в лікарню"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 74), 5, 'Що оповідачка планує на наступний травень?', 'Вдягнути свою вишиванку', '["Поїхати до Торонто","Пошити сукню","Купити фотоапарат"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 75, 'Гуцульські традиції', '["Дорога в Карпати весь час повертала, і старий автобус їхав зовсім повільно. Гуцули живуть тут, серед лісів, річок і крутих схилів. Минулого літа я потрапив до них уперше. У маленькому музеї нам показали святковий одяг. Кольорів було стільки, що я не одразу побачив крій. Кожна річ мала свій настрій.","Потім майстер показав дерев''яні речі з різьбленням. На них були прості узори, листя і лінії. Він сказав, що така робота потребує часу, гострого ножа і дуже спокійних рук. Ніж рухався так само повільно, як автобус уранці. У дворі вже налаштовували інструменти. Люди готувалися до маленького виступу для гостей.","Найбільше мені запам''ятався танець гуцулка. Скрипка почала швидко, і ноги самі пішли в такт. Танцюристи рухалися легко, а музика піднімала з лавок навіть найстарших. Додому я їхав з адресою того майстра в телефоні."]', 1, 1, 75) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 75), 1, 'Куди оповідач поїхав минулого літа?', 'У Карпати', '["До Одеси","До Варшави","До Полтави"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 75), 2, 'Про кого він більше дізнався?', 'Про гуцулів', '["Про козаків","Про волонтерів","Про туристів"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 75), 3, 'Що показали в невеликому музеї?', 'Святковий одяг', '["Старі автобуси","Морські мушлі","Шкільні зошити"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 75), 4, 'Які речі показав майстер?', 'Дерев''яні речі з різьбленням', '["Скляні чашки","Картонні коробки","Металеві квитки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 75), 5, 'Який танець найбільше запам''ятався?', 'Гуцулка', '["Гопак","Вальс","Полька"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 76, 'Чорнобиль: пам''ять і уроки', '["У Прип''яті досі стоять будинки, у яких ніхто не живе. На балконах ростуть дерева, а в квартирах залишилися чужі речі. Місто спорожніло за один день. Двадцять шостого квітня 1986 року на Чорнобильській атомній електростанції стався вибух. Люди дізналися про це не одразу. Потім прийшли автобуси, і десятки тисяч людей вивезли з їхніх домівок.","Багатьом сказали, що вони повернуться за три дні. Вони брали документи, трохи одягу і іграшки. Повернутися не вдалося ні через тиждень, ні через рік. Цілі села довелося залишити назавжди. Люди починали життя заново в чужих містах, серед незнайомих сусідів. Найважче було старим, які не хотіли їхати. Дехто ще довго возив із собою ключі від зачинених дверей.","Сьогодні про Чорнобиль говорять спокійно, без зайвих подробиць. Ця історія нагадує, що за землю і за майбутні покоління завжди хтось відповідає. Тому перед великими рішеннями люди тепер питають ще раз. Ключі так і не знадобилися."]', 1, 1, 76) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 76), 1, 'Коли сталася аварія на Чорнобильській АЕС?', 'Двадцять шостого квітня 1986 року', '["Двадцять другого січня 1919 року","Двадцять восьмого червня 1996 року","Першого жовтня 2022 року"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 76), 2, 'Що мусили зробити багато людей після аварії?', 'Залишити свої домівки', '["Піти на концерт","Купити квитки","Пекти паску"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 76), 3, 'Що люди брали із собою, коли їхали?', 'Документи, трохи одягу і іграшки', '["Меблі і килими","Тільки гроші","Книжки і фото"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 76), 4, 'Що Чорнобиль нагадує людям?', 'Що за землю і майбутні покоління хтось відповідає', '["Треба більше шуміти","Треба швидше їхати","Треба забути минуле"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 76), 5, 'Що люди роблять перед великими рішеннями?', 'Питають ще раз', '["Поспішають","Мовчать","Забувають про минуле"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 77, 'Ринок «Привоз» в Одесі', '["«Привоз» починається задовго до входу. Уже на тротуарі стоять ящики, відра і перші продавці. Друзі казали, що це один із найвідоміших ринків в Україні. Я прийшов о сьомій ранку, і всередині вже гуло. Далі я йшов повільно, бо не хотів нічого пропустити.","В одному ряду продавали свіжу рибу, ще мокру і блискучу. Поруч лежали фрукти, зелень і сир у великих мисках. А в кінці ряду починалися старі речі: чашки, книжки, годинники і маленькі картини. Продавці не мовчали ні хвилини. Вони жартували, кликали, хвалили свій товар і сміялися одне з одного. Одна жінка сварилася із сусідкою і одночасно зважувала мені яблука.","Ринок був схожий на театр, де вистава йде без перерви. Кожен продавець мав свій голос і свою роль. Мені побажали гарного дня так, ніби ми давно знайомі."]', 1, 1, 77) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 77), 1, 'Куди друзі порадили піти в Одесі?', 'На ринок «Привоз»', '["До оперного театру","На Андріївський узвіз","До школи"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 77), 2, 'Коли на ринку було багато людей?', 'О сьомій ранку', '["Опівночі","Після вечері","У понеділок на уроці"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 77), 3, 'Що продавали на одному ряду?', 'Свіжу рибу', '["Книжки для школи","Пампушки","Вишиванки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 77), 4, 'На що ринок здавався схожим оповідачу?', 'На театр', '["На лікарню","На тихий клас","На автобус"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 77), 5, 'Що оповідач купив на ринку?', 'Кілька яблук', '["Мед і варення","Квиток","Маленький магніт"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 78, 'Як я готуюся до іспиту', '["Я — Катя, і мій календар на цей тиждень уже розписаний. Іспит через сім днів. У неділю я сіла за стіл і розписала кожен день окремо. У плані є конспекти, картки, тести і обов''язкові перерви на каву. Найважливіше — щовечора викреслювати те, що зробила.","У понеділок і вівторок я перечитую записи з уроків. Те, що не тримається в голові, переписую на маленькі картки. З одного боку слово, з другого — короткий приклад. Картки живуть у кишені і йдуть зі мною навіть у транспорт. Увечері я проходжу онлайн-тести і дивлюся, де помилилася. Помилки виписую окремо і повертаюся до них наступного дня.","Торік я вчила все в останній вечір і майже нічого не пам''ятала вранці. Коли робиш потроху, голова встигає за руками і не втомлюється. Завтра перегляну картки ще раз і ляжу спати раніше."]', 1, 1, 78) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 78), 1, 'Як звати дівчину, яка готується до іспиту?', 'Катя', '["Марія","Олена","Ярина"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 78), 2, 'Коли в Каті буде іспит?', 'За тиждень', '["Завтра","Через місяць","Сьогодні ввечері"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 78), 3, 'Що Катя зробила в неділю?', 'Простий план на кожен день', '["Листівку","Писанку","Кошик"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 78), 4, 'Що Катя робить зі словами, які часто забуває?', 'Робить картки', '["Пече млинці","Пише список покупок","Малює квіти"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 78), 5, 'Що Катя планує зробити перед іспитом?', 'Лягти спати раніше', '["Піти на ринок","Подивитися феєрверки","Спекти пампушки"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 79, 'День пам''яті Голодомору: свічка у вікні', '["Молодша сестра першою помітила свічку на столі. Була четверта субота листопада, і темніло вже зовсім рано. Вона спитала, чому свічка стоїть, а ми не святкуємо. Сестра кличе мене Ганнусею, коли їй щось незрозуміло. Пояснювати випало мені, бо я старша на чотири роки. Я сказала їй просто: у 1932-1933 роках Голодомор забрав дуже багато життів.","О сьомій вечора у вікнах по всій країні з''являються вогники. Акція називається «Запали свічку». Мама поставила свічку на підвіконня, а сестрі дала сірник. Та довго не могла його запалити і сердилася на власні пальці. Потім вогник усе-таки з''явився, і вона завмерла. У сусідньому будинку теж світилося одразу три вікна. Далі по вулиці загорілося ще одне, потім ще.","Сестра спитала, що означає ця свічка. Я відповіла: «ми пам''ятаємо». Більше вона нічого не питала. Ми стояли біля вікна, поки віск не потік на блюдце."]', 1, 1, 79) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 79), 1, 'Коли Ганна згадує жертв Голодомору?', 'У четверту суботу листопада', '["Першого вересня","Двадцять п''ятого грудня","У третій четвер травня"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 79), 2, 'Кому Ганна пояснює значення свічки?', 'Молодшій сестрі', '["Учительці","Сусідці","Татові"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 79), 3, 'Як називається дія із запалюванням свічки?', 'Запали свічку', '["Перший дзвоник","Ланцюг єдності","Країна Мрій"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 79), 4, 'Куди мама ставить свічку?', 'На підвіконня', '["На парту","У рюкзак","На ринок"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 79), 5, 'Що означає свічка?', 'Ми пам''ятаємо', '["Ми поспішаємо","Ми святкуємо гучно","Ми купуємо подарунки"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 80, 'Традиційний весільний обряд', '["Вінок для нареченої плетуть заздалегідь, іноді за кілька днів. У нього вплітають живі квіти і кольорові стрічки. Це одна з найстаріших весільних традицій в Україні. У різних родинах усе трохи інакше, але головне збігається. Гості приходять у гарному одязі, з квітами і подарунками. Двір наповнюється голосами задовго до початку.","На одному з обрядів молодята тричі обходять стіл. Старші родичі стежать, щоб коло не розірвалося. Так починається спільне життя. Потім співають, і хтось обов''язково заспівує перший. За піснями йдуть танці, і потім уже ніхто не хоче сідати за стіл. Молодята встигають не все, але їм ніхто не дорікає.","Нарешті всі сідають за великий стіл. На ньому борщ, вареники, м''ясо, салати і солодке. Діти дивляться на танці, а бабусі згадують власні весілля. Котрась із них скоро покаже онуці, як плести вінок."]', 1, 1, 80) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 80), 1, 'Коли починають плести вінок?', 'Заздалегідь, іноді за кілька днів', '["За годину до весілля","За рік","Уранці того ж дня"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 80), 2, 'Що часто має наречена?', 'Квітковий вінок', '["Рюкзак","Теплу шапку","Вудку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 80), 3, 'Скільки разів молодята обходять стіл?', 'Тричі', '["Один раз","П''ять разів","Десять разів"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 80), 4, 'Що означає цей обряд?', 'Нове спільне життя', '["Початок уроку","Кінець подорожі","Похід до магазину"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 80), 5, 'Як традиції переходять від старших до молодших?', 'Бабуся показує онуці, як плести вінок', '["Через чеки з магазину","Через автобусні квитки","Через онлайн-тести"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 81, 'День Героїв Небесної Сотні: пам''ять і вибір', '["На вчительському столі стояла свічка і кілька білих паперових квітів. Ми зайшли в клас і стишили голоси. Двадцятого лютого Україна вшановує Героїв Небесної Сотні. Це люди Революції Гідності, які загинули на Майдані у 2014 році. Учителька говорила простими словами і жодного разу не підвищила голосу. Хтось запитав, скільки їм було років, і ніхто не відповів одразу.","Вона сказала, що ці люди хотіли вільної і справедливої країни. Потім ми довго говорили про саме слово «свобода», і клас не поспішав. Я думав, що воно означає робити те, що хочеш. Виявилося, що це тільки половина. Друга половина — відповідати за те, що ти зробив. Про це на уроках раніше не говорили.","Після дзвінка ніхто не побіг у коридор. Я сидів біля вікна і довго дивився, як за склом іде мокрий сніг. Свічка на столі догоріла майже до кінця. Додому я йшов повільніше, ніж завжди."]', 1, 1, 81) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 81), 1, 'Коли в школі був урок про Героїв Небесної Сотні?', 'Двадцятого лютого', '["Дев''ятнадцятого січня","Першого жовтня","У четверту суботу листопада"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 81), 2, 'Кого вшановує Україна цього дня?', 'Героїв Революції Гідності', '["Учителів музики","Моряків","Першокласників"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 81), 3, 'Що стояло на вчительському столі?', 'Свічка і паперові квіти', '["Карта і стрічки","Піаніно і ноти","Кава і шоколад"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 81), 4, 'Чого хотіли ці люди?', 'Вільної і справедливої країни', '["Нової кав''ярні","Довгих канікул","Гучного концерту"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 81), 5, 'Що свобода також означає для оповідача?', 'Відповідати за те, що зробив', '["Можливість не слухати","Гру без правил","Покупку подарунків"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 82, 'Сільська гостинність', '["Автобус висадив нас біля воріт, і господарі вже стояли там і махали руками. Нас було восьмеро, і в українське село я приїхала вперше. У хаті на столі парував борщ і лежав домашній хліб. Поруч стояли сметана і зелень, зрізана хвилину тому. Питати нас ніхто не став.","Після обіду господар повів нас у сад. Там росли яблуні, сливи, помідори і огірки. Він давав куштувати геть усе, повз що ми проходили. Потім господиня відчинила льох, і зверху війнуло холодом. На полицях стояли банки з варенням, огірками і компотом. Вона рахувала їх уголос і збилася на третьому ряду.","Ми об''їздили багато країн, але такої гостинності ще ніде не бачили. Увечері нам винесли чай просто у двір. Ніхто нікуди не поспішав, і розмова сама собою стихла. Я досі пам''ятаю, як пахнув той льох."]', 1, 1, 82) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 82), 1, 'Куди туристка приїхала минулого літа?', 'В українське село', '["До великого міста","До Варшави","На морський курорт"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 82), 2, 'Де господарі зустріли гостей?', 'Біля воріт', '["На вокзалі","Біля школи","У музеї"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 82), 3, 'Що стояло на столі?', 'Борщ, хліб, сметана і зелень', '["Кава, шоколад і вода","Паска, яйця і сир","Сік, шоколад і чек"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 82), 4, 'Що господиня показала після саду і городу?', 'Льох із банками', '["Новий автобус","Шкільний клас","Морський порт"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 82), 5, 'Що туристи пили увечері у дворі?', 'Чай', '["Каву","Узвар","Сік"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 83, 'Екологія і Карпати', '["Деякі буки в карпатських лісах старші за будь-яку хату в найближчому селі. Їм по кілька сотень років. Такі ліси більше ніде в Європі не збереглися так добре. Між стовбурами майже завжди сутінки, навіть опівдні. Повітря там вологе і пахне мокрою корою. Туристи в таких місцях самі починають говорити тихіше.","Небезпека приходить не з погодою, а з дорогою. Там, де ліс вирубують без контролю, схили залишаються голими. Після дощу вода біжить униз дуже швидко і несе із собою верхню землю. Струмки міліють, а звірам стає нікуди подітися. Молоді дерева на місці старих ростуть десятиліттями. Один зрізаний схил видно з дороги за кілометр.","Про це першими заговорили місцеві школярі і студенти. Вони прибирають стежки, проводять зустрічі і збирають підписи. Листи до громади вони пишуть від руки, по одному на кожен клас. Підписів під ними щороку більше."]', 1, 1, 83) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 83), 1, 'Які ліси є в Карпатах?', 'Такі, яких більше ніде в Європі немає', '["Піщані ліси","Міські ліси","Штучні ліси без дерев"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 83), 2, 'Які дерева ростуть у Карпатах?', 'Буки, деяким по кілька сотень років', '["Пальми і кактуси","Яблуні і груші","Соняшники"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 83), 3, 'Що стається, коли дерева вирубують без контролю?', 'Схили залишаються голими', '["Море стає теплішим","Місто стає більшим","Школа стає тихішою"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 83), 4, 'Хто говорить про проблему лісів?', 'Місцеві школярі і студенти', '["Тільки туристи","Тільки продавці","Тільки лікарі"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 83), 5, 'Що роблять молоді люди?', 'Прибирають стежки і збирають підписи', '["Печуть паску","Купують яблука","Пишуть іспити"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 84, 'Мій улюблений український письменник', '["Портрет Шевченка висить у нашому класі над дошкою. Я дивилася на нього чотири роки і майже ніколи не помічала. Минулого тижня я готувала про нього розповідь. Учителька сказала, що це найвідоміший поет України. Виявилося, що я не знала про нього майже нічого.","Удома бабуся дістала з шафи стару книжку «Кобзар». Обкладинка була потерта, а всередині лежала засушена синя квітка. Таку книжку тримали в багатьох українських домівках. Шевченко писав про свободу, рідну землю і звичайних людей. Не про королів і не про битви, а про тих, хто поруч. Бабуся прочитала мені один вірш уголос і зупинилася на середині.","Деякі слова я не зрозуміла, і вона пояснила їх своїми. Читати виявилося легше вголос. «Кобзар» тепер лежить у мене на столі, поруч із підручниками. Я дійшла до сорок другої сторінки."]', 1, 1, 84) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 84), 1, 'Про кого оповідачка готувала розповідь?', 'Про Тараса Шевченка', '["Про Лесю Українку","Про Івана Франка","Про Миколу Гоголя"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 84), 2, 'Ким учителька назвала Шевченка?', 'Найвідомішим поетом України', '["Найкращим кухарем","Відомим лікарем","Першим космонавтом"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 84), 3, 'Яку книжку знають багато українців?', 'Кобзар', '["Буквар","Атлас","Щоденник"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 84), 4, 'Про що писав Шевченко?', 'Про свободу, рідну землю і людей', '["Про каву і шоколад","Про автобуси і квитки","Про спорт і басейн"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 84), 5, 'Звідки бабуся дістала «Кобзар»?', 'З шафи', '["З бібліотеки","З магазину","Зі школи"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 85, 'День Соборності: одна країна, різні голоси', '["Учитель повісив на дошці стару карту з іншими кордонами. На ній Україна була поділена на дві частини. Двадцять другого січня в країні відзначають День Соборності. У 1919 році ці частини вирішили стати однією державою. Легко тоді не було нікому. На заході і на сході люди жили по-різному вже кілька поколінь поспіль.","Різні традиції, різні звички, а часом навіть різні слова для тих самих речей. Хтось жив біля моря, хтось у горах, хтось у степу. Учитель спитав нас, що могло їх тоді об''єднати. Ми довго не могли відповісти. Виявилося, що спільна мрія про незалежність важила більше за всі відмінності. Домовитися вони змогли не одразу, але змогли.","Після уроку я думав про це всю дорогу додому. Єдність — це не коли всі однакові. Країна з різними голосами багатша за країну з одним. Удома дід сказав, що його село тоді було по той бік лінії."]', 1, 1, 85) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 85), 1, 'Коли в школі говорили про День Соборності?', 'Двадцять другого січня', '["Двадцять восьмого червня","Дев''ятнадцятого січня","Першого вересня"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 85), 2, 'Що хотіли українські землі в 1919 році?', 'Стати однією державою', '["Бути окремо","Їхати до моря","Відкрити ринок"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 85), 3, 'Що дивилися учні на уроці?', 'Карту', '["Відео про кафе","Фото моря","Писанки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 85), 4, 'Що було сильнішим за різні звички?', 'Спільна мрія про незалежність', '["Гучна музика","Довга дорога","Холодна погода"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 85), 5, 'Що не означає єдність?', 'Однаковість', '["Повагу","Спільну мрію","Різні голоси"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 86, 'Холодець на Різдво', '["Холодець у нас варять двічі на рік — на Різдво і на Новий рік. Починається все звечора, коли на плиту ставлять велику каструлю. У ній кілька годин вариться свинина або курка. Кухня тоді пахне так, що з неї не хочеться виходити. Мама каже, що раніше ніж за чотири години пробувати немає сенсу.","Пізно ввечері дорослі розливають гарячий холодець у широкі миски. Далі його виносять на балкон і залишають до ранку. Уночі туди краще не заглядати. Зранку страва вже тримає форму і блищить, як скло. Бабуся кладе зверху кілька кружечків моркви. Робить вона це щоразу однаково. Ніхто не питає її чому.","За столом тато бере холодець із хроном, а дідусь — з гірчицею. Мені більше смакує просто з хлібом. Сестра їсть саму моркву. Миска порожніє швидше за все інше на столі."]', 1, 1, 86) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 86), 1, 'Коли в родині часто готують холодець?', 'На Різдво і Новий рік', '["На День знань","На іспит","На День Конституції"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 86), 2, 'Що кілька годин вариться у каструлі?', 'Свинина або курка', '["Рис або гречка","Яблука або груші","Сік або чай"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 86), 3, 'Куди дорослі розливають холодець?', 'У миски', '["У чашки","У пакети","У коробки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 86), 4, 'Чим бабуся прикрашає холодець?', 'Морквою', '["Шоколадом","М''ятою","Квітами"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 86), 5, 'З чим тато їсть холодець?', 'З хроном', '["З медом","З морозивом","З варенням"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 87, 'Дванадцять страв на Святий вечір', '["Рахувати тарілки в нашому домі щороку доручають мені. Їх має бути дванадцять, і жодної менше. Сьомого січня наша родина святкує Різдво за юліанським календарем. Так роблять багато православних українців. Увечері перед святом ми накриваємо стіл на Святий вечір. Бабуся ще зранку перевіряє, чи всім вистачить узвару.","Першою на стіл ставлять кутю, і чіпати її поки не можна. Далі йдуть узвар, вареники з капустою, голубці і смажена риба. Бабуся додає гриби, квасолю і два простих салати. Усі назви я не запам''ятовую, але бачу, що кожна страва має своє місце. Дванадцятою виявляється тарілка, про яку всі забули. Її приносять останньою, і рахунок нарешті сходиться.","У хаті пахне узваром і теплим хлібом. Ми говоримо тихо і чекаємо тих, хто ще в дорозі. Коли заходить останній, стільців уже не вистачає. Хтось приносить табуретку, і всі сідають."]', 1, 1, 87) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 87), 1, 'Коли родина святкує Різдво за юліанським календарем?', 'Сьомого січня', '["Двадцять п''ятого грудня","Двадцять другого січня","Першого жовтня"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 87), 2, 'Скільки пісних страв має бути на столі?', 'Дванадцять', '["Три","Сім","Двадцять"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 87), 3, 'Що допомагає рахувати оповідач?', 'Тарілки', '["Свічки","Квитки","Гроші"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 87), 4, 'Що є на столі?', 'Кутя, узвар і вареники з капустою', '["Піца, сік і шоколад","Кава, печиво і торт","Мед, варення і яблука"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 87), 5, 'Що приносять останнім, коли не вистачає місця?', 'Табуретку', '["Ще одну тарілку","Другий стіл","Свічку"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 88, 'Чому я вивчаю іноземні мови', '["Мій зошит поділений навпіл: ліва половина англійська, права польська. Мене звати Оксана, і я веду його вже другий рік. Англійська — для фільмів, пісень і подорожей. Польську вчу через двоюрідних сестер, які давно живуть у Польщі. Займаюся тричі на тиждень і виписую нові слова стовпчиком.","На курсах я вже знайшла двох подруг. Одна вчить англійську з нуля, а друга приїхала з Луцька. Ми пишемо одне одному короткі повідомлення різними мовами. Помилки виправляємо відразу і майже без сорому. Минулого місяця я вперше зрозуміла цілу пісню без жодного перекладу і без словника. Слухала її потім разів десять.","Я хочу працювати перекладачкою або журналісткою. Для цього двох мов замало, і я про це вже знаю. Іноді навчання набридає, особливо довга граматика. Але зошит уже майже закінчився, і я купила другий."]', 1, 1, 88) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 88), 1, 'Які мови вивчає Оксана?', 'Англійську і польську', '["Німецьку і французьку","Італійську і грецьку","Іспанську і турецьку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 88), 2, 'Для чого Оксані потрібна англійська?', 'Для фільмів, пісень і подорожей', '["Для ферми","Для приготування борщу","Для купівлі риби"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 88), 3, 'Куди Оксана записує нові слова?', 'У зошит', '["На стіну","У конверт","На квиток"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 88), 4, 'Скільки подруг Оксана знайшла на курсах?', 'Двох подруг', '["Одну подругу","Трьох подруг","П''ять подруг"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 88), 5, 'Ким Оксана мріє працювати?', 'Перекладачкою або журналісткою', '["Лікаркою або продавчинею","Кухаркою або фермеркою","Співачкою або танцівницею"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 89, 'Допомога ветеранам', '["Суботній ранок у громадському центрі починається рівно о дев''ятій. Волонтери приходять першими і беруть список справ. Він щотижня інший і завжди довший, ніж здається. Потім приходять ветерани — по документи, по продукти, на розмову. Хтось приносить папку з документами, хтось порожню сумку. Ніхто нікого не квапить.","Одні волонтери сідають заповнювати заяви і шукати потрібні довідки. Інші йдуть до магазину і несуть назад важкі пакети. Двоє щосуботи супроводжують чоловіка на реабілітацію і чекають його в коридорі. Розмови починаються самі, десь на третьому поверсі або в черзі до ліфта. Після справ усі п''ють чай із одного чайника. Тоді й розповідають найбільше.","Керівниця центру каже, що самої пам''яті замало, якщо нема кому донести сумку. Волонтери втомлюються, але до вечора список завжди порожній. Наступної суботи приходять ті самі люди і ще двоє нових."]', 1, 1, 89) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 89), 1, 'Де щосуботи зустрічаються молоді волонтери?', 'У громадському центрі', '["У кафе","На ринку","У музеї"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 89), 2, 'Кому потрібна проста практична допомога?', 'Ветеранам', '["Туристам","Продавцям","Першокласникам"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 89), 3, 'Що допомагають зробити одні волонтери?', 'Заповнити заяви і знайти довідки', '["Спекти торт","Вивчити пісню","Купити квиток"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 89), 4, 'Куди інші волонтери супроводжують людину?', 'На реабілітацію', '["На концерт","До моря","На іспит"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 89), 5, 'Що, за словами керівниці центру, також дуже потрібне?', 'Щоб було кому донести сумку', '["Гучні промови","Довгі суперечки","Нові свята"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 90, 'Кава по-львівськи', '["Двері кав''ярні виявилися такими низькими, що я мимоволі нахилилася. Усередині пахло смаженою кавою і чимось солодким. Львів часто називають кавовою столицею України. Тут кав''ярня стоїть майже в кожному дворі старого міста. На стінах висіли старі фото і чорна дерев''яна вивіска. Біля вікна сиділи студенти з книжками і однією чашкою на двох.","Офіціант приніс меню і порадив каву по-львівськи. Він сказав, що в кожній кав''ярні тут свій рецепт і свій характер. Я взяла те, що порадили. Каву подали в маленькій чашці, а поруч поставили шоколад і склянку холодної води. Вода поруч була зовсім крижана.","Я пила повільно і дивилася у вікно. Люди йшли по бруківці, і десь поруч тихо грав акордеон. Шоколад робив каву м''якшою, а вода повертала смак назад. Свою чашку я допивала останньою в залі."]', 1, 1, 90) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 90), 1, 'Куди оповідачка зайшла у Львові?', 'До маленької кав''ярні', '["До музею","До школи","До лікарні"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 90), 2, 'Як часто називають Львів?', 'Кавовою столицею України', '["Морською столицею України","Спортивною столицею України","Зимовою столицею України"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 90), 3, 'Що висіло на стінах кав''ярні?', 'Старі фото', '["Карти світу","Вишиті рушники","Шкільні грамоти"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 90), 4, 'Що порадив офіціант?', 'Каву по-львівськи', '["Яблучний сік","Гарячий борщ","Холодець"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 90), 5, 'З чим подали каву?', 'З шоколадом і холодною водою', '["З медом і варенням","З хлібом і сіллю","З м''ятою і лимоном"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 91, 'Трійця і клечання', '["Зелень на базар привозять просто снопами. Ми з мамою купуємо аж дві оберемки і ледве несемо їх додому. Трійця приходить на п''ятдесятий день після Великодня. Мама рахує ці дні на календарі щовесни. Удома ми спершу відсуваємо килим і миємо підлогу. Тільки після цього можна братися за гілки.","Потім починається найцікавіше. Зелені гілки ставимо біля дверей, а свіжі трави кладемо на підвіконня. Бабуся каже, що цей звичай називається клечання. Слово я запам''ятав з першого разу. Тато приносить ще кілька гілочок для коридору. Я ставлю маленький букет просто на кухонний стіл. До вечора зелень є в кожній кімнаті.","У квартирі пахне м''ятою і мокрим листям. Так пахне двір після дощу, коли все починається спочатку. Мама вимикає світло, а зелень усе одно видно біля дверей. Уранці я прокинувся раніше за будильник — від запаху."]', 1, 1, 91) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 91), 1, 'Що ставлять біля дверей на Трійцю?', 'Зелені гілки', '["Свічки","Кошик з яблуками","Вишитий рушник"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 91), 2, 'Що оповідач із мамою купують перед Трійцею?', 'Зелень', '["Каву","Квитки","Морозиво"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 91), 3, 'Коли приходить Трійця?', 'На п''ятдесятий день після Великодня', '["Першого вересня","Через три дні після Нового року","У четверту суботу листопада"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 91), 4, 'Як називається звичай із зеленими гілками і травами?', 'Клечання', '["Колядка","Писанка","Гуцулка"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 91), 5, 'Куди оповідач ставить маленький букет?', 'На кухонний стіл', '["На шкільну дошку","У рюкзак","На балкон"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 92, 'Переваги роботи онлайн', '["Сестрин ноутбук стоїть на кухонному столі щодня з восьмої ранку. Іноді вона бере його і йде в тиху кав''ярню за рогом. Так тепер працює багато українців. Хтось із її колег живе у Львові, а хтось торік переїхав до Варшави. Бачаться вони тільки на екрані.","Спочатку я думала, що це найлегша робота на світі. Хочеш — працюй у піжамі, хочеш — узагалі не вставай. Сестра каже, що саме тут усе найчастіше й ламається. Щоранку вона пише розклад і ставить у нього час для перерв. Телефон на цей час лежить екраном донизу. Без розкладу день зникає, а справи залишаються на місці.","Одного разу я сиділа поруч у кав''ярні цілу годину. Кава біля неї так і застигла холодною. Увечері вона закриває ноутбук рівно о шостій і йде гуляти. Кухонний стіл до ранку знову стає кухонним."]', 1, 1, 92) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 92), 1, 'Хто працює онлайн?', 'Сестра', '["Молодший брат","Бабуся","Тато"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 92), 2, 'Де сестра може працювати з ноутбуком?', 'Вдома або в тихій кав''ярні', '["Тільки в школі","Тільки на фермі","Тільки біля річки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 92), 3, 'Що лежить екраном донизу під час роботи?', 'Телефон', '["Ноутбук","Книжка","Годинник"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 92), 4, 'Що сестра пише щоранку?', 'Розклад', '["Лист бабусі","Рецепт борщу","Вірш"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 92), 5, 'Що стається без розкладу?', 'День зникає, а справи стоять', '["Робота стає легшою","Кава не холоне","Ноутбук вимикається"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 93, 'Водохреща', '["Мороз того ранку був такий, що сніг рипів під ногами. Ми з татом вийшли з дому ще затемна, о сьомій. Дев''ятнадцятого січня в Україні святкують Водохреща. До річки йшли не тільки ми. Біля води вже стояли люди і чомусь говорили пошепки. Ніхто нікуди не поспішав.","У кризі був вирубаний рівний отвір і поставлені дерев''яні сходи. Кілька людей зайшли у воду просто в такий мороз. Заходили обережно, трималися за поручень і виходили дуже швидко. На березі їх одразу загортали в рушники. Кажуть, що ця вода очищає і тіло, і душу на цілий рік. Хтось на березі рахував уголос секунди.","Додому ми поверталися вже видною дорогою. Мама налила нам гарячого чаю з лимоном. Я грів об чашку руки і довго не міг їх відчути. Тато сидів навпроти і теж мовчав."]', 1, 1, 93) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 93), 1, 'Коли в Україні святкують Водохреща?', 'Дев''ятнадцятого січня', '["Двадцять першого листопада","У третій четвер травня","Сьомого січня"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 93), 2, 'Куди оповідач іде з татом?', 'До річки', '["До кафе","На ринок","До школи"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 93), 3, 'Коли оповідач із татом вийшли з дому?', 'Ще затемна, о сьомій', '["Опівдні","Після обіду","Пізно ввечері"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 93), 4, 'Що роблять деякі сміливі люди?', 'Заходять у воду в мороз', '["Печуть паску","Співають у класі","Плетуть вінки"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 93), 5, 'Що мама наливає після прогулянки?', 'Гарячий чай з лимоном', '["Холодний сік","Каву по-львівськи","Узвар"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 94, 'День Гідності та Свободи: що він означає сьогодні', '["Тато завжди відповідає одразу, на будь-яке питання. Того вечора він не відповів. Двадцять першого листопада ми мали урок про День Гідності та Свободи. Учителька сказала, що революції почалися у 2004 і 2013 роках. Для нас це сторінки в підручнику. Для дорослих у класі це був би зовсім інший урок. Я слухав і весь урок думав про свого тата.","Після уроку я прийшов додому і запитав тата, чи був він на Майдані. Тато не відповів одразу. Він поставив чашку на стіл і подивився у вікно. Потім назвав мене повним ім''ям — Олексієм. Сказав, що пам''ятає той час дуже добре, до дня. Але говорити про нього легко не завжди.","Голос у нього став тихішим, ніж звичайно. Тато сказав, що люди тоді хотіли поваги, свободи і чеснішої країни. Більше я нічого не питав. Ми досиділи до кінця чайника мовчки."]', 1, 1, 94) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 94), 1, 'Як звати хлопця в історії?', 'Олексій', '["Марко","Сашко","Петрик"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 94), 2, 'Коли в школі говорили про День Гідності та Свободи?', 'Двадцять першого листопада', '["Дев''ятнадцятого січня","Першого жовтня","Двадцять восьмого червня"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 94), 3, 'Які роки назвала учителька?', '2004 і 2013', '["1919 і 1996","1932 і 1933","1986 і 2022"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 94), 4, 'Про що Олексій запитав тата?', 'Чи він був на Майдані', '["Чи він був у Львові","Чи він купив квиток","Чи він знає рецепт"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 94), 5, 'Чого, за словами тата, хотіли люди?', 'Поваги, свободи і чеснішої країни', '["Морозива і подарунків","Гучного концерту","Нової кав''ярні"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 95, 'Народна медицина в Україні', '["Коли я застуджуюся, бабуся приходить на кухню зі своїми баночками. У неї їх ціла полиця, і на кожній наклейка з роком і назвою. Усередині сухий чебрець, материнка і м''ята. Мед стоїть окремо, у великій банці з дерев''яною ложкою. Малинове варення дістають із шафи тільки в такі дні.","Спершу мама телефонує лікарці й докладно розповідає про температуру. Тільки після цього на плиту ставлять чайник. Бабуся заварює чебрець, кидає туди ложку меду і накриває чашку блюдцем. Каже, що так довше тримається тепло. Ліки лежать поруч із чашкою, на тій самій серветці. Одне іншому не заважає.","Чай я п''ю дуже повільно, бо він гарячий і пахне травами. Потім лягаю під ковдру і беру книжку. Бабуся тихо зачиняє двері й забирає із собою навіть кота. Так день минає повільніше, ніж усі інші."]', 1, 1, 95) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 95), 1, 'Хто приходить на кухню, коли оповідач застуджується?', 'Бабуся', '["Учителька","Сусідка","Офіціант"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 95), 2, 'У кого мама завжди питає поради?', 'У лікарки', '["У продавця","У туриста","У музиканта"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 95), 3, 'Із чого бабуся робить чай?', 'Із чебрецю, материнки або м''яти', '["Із кави і шоколаду","Із яблук і груш","Із моркви і капусти"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 95), 4, 'Що бабуся додає до чашки?', 'Ложку меду', '["Сіль","Кетчуп","Холодну воду"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 95), 5, 'Що робить мама, якщо потрібно?', 'Телефонує лікарці', '["Пише лист","Купує квиток","Відкриває музей"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 96, 'День Конституції: права і обов''язки', '["У кожній бібліотеці країни є тонка книжка в синій обкладинці. Це Конституція України, головний закон держави. Її ухвалили двадцять восьмого червня 1996 року. Відтоді цей день є державним святом. Книжка невелика, але саме вона визначає правила для всіх. Прочитати її може будь-хто, і мова там простіша, ніж здається.","У Конституції записано, що людина має право говорити вільно. Має право вчитися і лікуватися. Має право не боятися за себе і свою родину. Ці права не залежать від того, багата людина чи ні. Але записане право і право, яке справді працює, — не одне й те саме. Демократія працює тоді, коли люди знають і права, і обов''язки.","Тому Конституцію читають не тільки юристи. Хтось перевіряє, чи має право на безкоштовну операцію. Хтось питає, чому в дворі зрубали дерева. Обов''язки в тій самій книжці й на тих самих сторінках."]', 1, 1, 96) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 96), 1, 'Коли ухвалили Конституцію України?', 'Двадцять восьмого червня 1996 року', '["Двадцять другого січня 1919 року","Дев''ятнадцятого січня","Першого вересня"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 96), 2, 'Що таке Конституція?', 'Головний закон країни', '["Шкільна пісня","Рецепт страви","Назва ринку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 96), 3, 'Де можна знайти Конституцію?', 'У кожній бібліотеці', '["Тільки в суді","Тільки в школі","Тільки в музеї"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 96), 4, 'Яке право записане в Конституції?', 'Право навчатися', '["Право шуміти","Право не поважати інших","Право губити речі"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 96), 5, 'Що однаково важливе для всіх громадян?', 'Права і обов''язки', '["Кава і шоколад","Квитки і чеки","Сніг і мороз"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 97, 'Фестиваль «Країна Мрій»', '["Учителька музики принесла на урок стару афішу. На ній великими літерами стояло: «Країна Мрій». Це відомий фестиваль етнічної музики. Раніше він щоліта проходив у Києві, просто неба. Туди приїжджали гурти з різних країн і з усіх куточків України. Афіша була пом''ята, з дірками від кнопок по кутах.","Потім ми дивилися коротке відео з того фестивалю. На сцені стояли люди у вишиванках, а перед сценою танцювали всі підряд. Музика починалася повільно, майже як колискова. Через хвилину під неї вже можна було стрибати. Барабан звучав сучасно, а голос — зовсім давно. Молоді люди в залі знали приспіви напам''ять і співали разом. Ніхто з них не виглядав так, ніби прийшов у музей.","Після уроку я знайшов кілька записів удома. Слухав їх до вечора, поки не сів телефон. Одну пісню поставив на будильник. Тепер прокидаюся під барабан."]', 1, 1, 97) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 97), 1, 'Від кого оповідач уперше почув про фестиваль?', 'Від учительки музики', '["Від бабусі","Від продавця","Від лікаря"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 97), 2, 'Який це фестиваль?', 'Етнічної музики', '["Спортивний фестиваль","Книжковий фестиваль","Фестиваль морозива"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 97), 3, 'Де раніше проходив фестиваль?', 'У Києві', '["В Одесі","У Варшаві","У маленькому селі"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 97), 4, 'Що оповідач бачив на екрані?', 'Сцену, людей у вишиванках і танці', '["Ринок, яблука і рибу","Лікаря, чай і ліки","Море, порт і кораблі"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 97), 5, 'Що оповідач знайшов удома після уроку?', 'Кілька записів', '["Старі квитки","Банки з медом","Новий рюкзак"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 98, 'Листи до рідних', '["Дорогі мамо і тату!","Пишу вам справжнього паперового листа, бо хочу, щоб ви тримали його в руках. Я вже два місяці живу за кордоном. Тут усе нове: вулиці, магазини, мова і навіть ранкова кава. Найдивніше тут те, що хліб продають уже нарізаним. Але я часто думаю про наш дім і вашу кухню.","Сьогодні я купила конверт і красиву марку в маленькій крамниці. Продавчиня довго вибирала мені марку з квітами. Знаю, що мама читає кожен мій лист кілька разів. Тато казав, що ви складаєте всі листи в коробку біля шафи. Порахуйте, будь ласка, скільки їх там уже. Коробка, мабуть, уже не закривається.","Я сумую за вами, але вчуся бути сміливою. Передайте привіт бабусі і нашому коту. Я скоро напишу знову і покладу в конверт нову марку. Обіймаю вас міцно. Ваша Олена."]', 1, 1, 98) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 98), 1, 'Кому Олена пише листа?', 'Мамі і татові', '["Бабусі і коту","Учительці","Подрузі з Харкова"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 98), 2, 'Якого листа пише Олена?', 'Паперового листа', '["Електронного листа","Короткого повідомлення","Шкільної заяви"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 98), 3, 'Скільки часу Олена живе за кордоном?', 'Два місяці', '["Один тиждень","Пів року","Три дні"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 98), 4, 'Що Олена купила в маленькій крамниці?', 'Конверт і марку', '["Каву і шоколад","Паску і яйця","Книжку і олівці"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 98), 5, 'Кому Олена просить передати привіт?', 'Бабусі і коту', '["Учительці і класу","Сусідам і продавцю","Тітці і дядьку"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 99, 'Українці у світі', '["Українську я почув у автобусі, за три зупинки від дому. Двоє чоловіків голосно говорили про футбол, і я мимоволі усміхнувся. Тут, за кордоном, таке трапляється частіше, ніж я думав. Українці живуть від Канади до Австралії. У великих містах і в містечках, про які ніхто не чув.","Мову тут бережуть найпростішим способом — розмовляють нею вдома. У неділю діти йдуть до школи вдруге за тиждень. Там вони вчать пісні, букви і короткі вірші. Раз на рік громада влаштовує фестиваль у міському парку. Варять борщ у великих каструлях і танцюють просто на траві до темряви. Вишиванки дістають навіть ті, хто носить їх раз на рік.","Коли в Україні стало важко, тут почали збирати гроші і ліки. Ніхто не домовлявся заздалегідь. Просто в один тиждень усі почали робити те саме. Тепер в автобусі я озираюся першим."]', 1, 1, 99) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 99), 1, 'Де живе оповідач?', 'За кордоном', '["У Карпатах","У маленькому селі","Біля школи"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 99), 2, 'Від Канади до якої країни живуть українці?', 'До Австралії', '["До Польщі","До Грузії","До Італії"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 99), 3, 'Де оповідач іноді чує українську мову?', 'В автобусі', '["Тільки вдома","Тільки в музеї","Тільки на річці"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 99), 4, 'Що діти вчать у недільних школах?', 'Пісні, букви і короткі вірші', '["Складні закони","Рецепти кави","Правила ринку"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 99), 5, 'Як українці за кордоном допомагають Україні?', 'Збирають гроші і ліки', '["Запускають феєрверки","Купують морозиво","Готують іспити"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 100, 'Одеса: місто між морем і степом', '["Одеса починається запахом ще до вокзалу. Море чути раніше, ніж видно. За містом одразу починається степ — рівний, жовтий і безкінечний. Між ними стоїть місто, у якому все це давно перемішалося між собою. Я приїжджаю сюди щоліта і гублюся в однакових дворах. Тут ніхто не показує дорогу мовчки.","Потьомкінські сходи згори здаються коротшими, ніж знизу. Я рахувала їх і двічі збилася. Хтось знизу гукнув мені правильну цифру. Увечері біля оперного театру збираються люди в гарному одязі. Квитків не було, тому ми слухали музику знадвору разом з іншими такими ж. Поруч продавали морозиво і голосно сперечалися про його ціну. Сперечалися весело, ніби це частина вистави.","Уранці я зайшла на «Привоз» по абрикоси для дороги. Продавчиня зважила кілограм і додала ще жменю зверху. Сказала, що я схожа на її молодшу доньку. Абрикоси я з''їла ще дорогою до моря."]', 1, 1, 100) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 100), 1, 'Коли оповідачка приїжджає до Одеси?', 'Щоліта', '["Взимку","Навесні","Восени"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 100), 2, 'Що оповідачка відчуває одразу?', 'Запах моря', '["Запах кави","Запах лісу","Запах фарби"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 100), 3, 'Куди оповідачка йде першого дня?', 'До Потьомкінських сходів', '["На Андріївський узвіз","До громадського центру","До школи"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 100), 4, 'Що оповідачка слухала біля оперного театру?', 'Музику знадвору', '["Концерт у залі","Вуличного музиканта","Шум порту"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 100), 5, 'Куди оповідачка заходить уранці?', 'На ринок «Привоз»', '["До музею","До церкви","У парк біля школи"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 101, 'Волонтерство як стиль життя', '["Волонтерський центр працює в колишньому меблевому магазині. Вивіску не знімали, тому там досі написано «Дивани». Після 2022 року такі центри відкрилися майже в кожному районі. Я приходжу сюди тричі на тиждень, після пар. Тут студенти, пенсіонери, вчителі і жінка з нашого під''їзду. Її я бачив тільки біля ліфта.","Одні плетуть маскувальні сітки, і руки в них зелені аж до ліктів. Інші збирають гроші на обладнання і рахують їх двічі. Хтось сортує одяг, ліки і продукти для гуманітарної допомоги. Я пакую коробки і пишу списки, щоб нічого не загубилося. Робота проста, але помилятися в ній не можна. Мій почерк тут уперше в житті став розбірливим.","Найбільше говорять не про роботу, а про звичайні речі. Хто де вчився, у кого нарешті зацвів кактус і чий кіт знову втік. Тому сюди й ходять — щоб не сидіти вдома самому. Коробок сьогодні вийшло сорок дві."]', 1, 1, 101) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 101), 1, 'Після якого року волонтерство стало звичайною частиною життя?', 'Після 2022 року', '["Після 1919 року","Після 1996 року","Після 1986 року"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 101), 2, 'Куди оповідач приходить кілька разів на тиждень?', 'До волонтерського центру', '["До кав''ярні","До річки","До опери"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 101), 3, 'Хто працює у центрі?', 'Студенти, пенсіонери, вчителі і сусідка', '["Тільки лікарі","Тільки туристи","Тільки продавці"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 101), 4, 'Що плетуть одні люди?', 'Маскувальні сітки', '["Вінки з квітів","Кошики","Шарфи"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 101), 5, 'Що оповідач часто робить?', 'Пакує коробки і пише списки', '["Готує каву","Співає пісні","Фотографує море"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 102, 'Що означає бути українцем', '["У шафі в бабусі висить вишиванка в білому чохлі. Дістають її двічі на рік і завжди чомусь мовчки. Бабуся каже, що її шила ще її мати. Мене назвали Яриною на честь тієї жінки. Паспорт у мене такий самий, як у всіх. А вишиванка одна. Я міряла її один раз, у сім років.","Бути українкою — це не місце народження. Це мова, яку я чую вдома щодня. Це пісні, які мама співала мені до сну. Це борщ, який у нас варять у неділю. Це червона калина біля воріт, гірка і дуже помітна. Кожна з цих речей зовсім маленька, а разом вони тримають.","Торік у нас двічі не було світла по чотири дні поспіль, узимку. Бабуся тоді дістала свічки і поставила на газ старий чайник. Сказала, що серце ламається не від темряви. Я запам''ятала."]', 1, 1, 102) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 102), 1, 'Як звати дівчину в історії?', 'Ярина', '["Олена","Ганна","Марія"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 102), 2, 'Що для Ярини означає бути українкою?', 'Мову, пісні, борщ і калину', '["Тільки паспорт","Тільки роботу онлайн","Тільки подорож до моря"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 102), 3, 'Що Ярина згадує, коли думає про Україну?', 'Борщ і червону калину', '["Каву і шоколад","Море і порт","Квиток і чек"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 102), 4, 'Що береже бабуся в шафі?', 'Стару вишиванку', '["Новий рюкзак","Маленький магніт","Книжку з віршами"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 102), 5, 'Що сказала бабуся, коли не було світла?', 'Що серце ламається не від темряви', '["Що треба лягати спати","Що світло скоро дадуть","Що свічок замало"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('A2', 103, 'Україна і світ: новий погляд', '["На уроці географії мене попросили показати Київ на карті. Половина класу думала, що це десь біля Москви. Я показав і сказав, що до моря звідти всього сім годин потягом. Про Україну тут почули через війну. Але питають мене не тільки про неї. Питають про музику, про художників і про те, що ми їмо на свята.","Нас таких у школі четверо. Ми, українці за кордоном, стали чимось на зразок маленьких послів. На Великдень я приніс пасок, і його з''їли за одну перерву. Мене питали, чому вона солодка і чому зверху біла глазур. Найважче було пояснити слово «незламність». Я сказав, що це коли ламається все навколо, а людина ні. Потім це слово вживали навіть учителі.","Друзі повторювали слово повільно, по складах. Одна дівчина записала його собі в телефон. Коли пояснюєш свою країну іншим, починаєш розуміти її сам. Тепер я не мовчу, коли при мені кажуть дурниці."]', 1, 1, 103) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 103), 1, 'Де живе оповідач?', 'За кордоном', '["В Одесі","У Карпатах","У селі"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 103), 2, 'Про що оповідач часто розповідає людям?', 'Про Україну', '["Про математику","Про автобуси","Про рецепт холодцю"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 103), 3, 'Ким іноді стають молоді українці за кордоном?', 'Маленькими послами', '["Продавцями на ринку","Учителями музики","Лікарями"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 103), 4, 'Що оповідач пояснює друзям?', 'Слово «незламність»', '["Слово «клечання»","Слово «кава»","Слово «іспит»"]');
INSERT INTO questions (story_id, display_order, prompt, correct_answer, wrong_answers_json) VALUES ((SELECT id FROM texts WHERE level = 'A2' AND display_order = 103), 5, 'Що стається, коли він пояснює свою країну іншим?', 'Він сам краще її розуміє', '["Він забуває рідну мову","Він менше сумує за домом","Він хоче поїхати далі"]');
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('B1', 1, 'Текст 1', '["Тут буде текст для цього уроку. Поки що ця сторінка залишається порожньою, бо вміст для рівня B1 ми додамо пізніше."]', 1, 1, 1) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled, question_index) VALUES ('B1', 2, 'Текст 2', '["Тут буде текст для цього уроку. Поки що ця сторінка залишається порожньою, бо вміст для рівня B1 ми додамо пізніше."]', 1, 1, 2) ON CONFLICT(level, display_order) DO UPDATE SET title = excluded.title, paragraphs_json = excluded.paragraphs_json, show_word_count = excluded.show_word_count, updated_at = CURRENT_TIMESTAMP;
